const defaultDataDir = join(homedir(), '.buildaharness', 'personal-assistant')
const defaultConfigStore = new NodeConfigStore(join(defaultDataDir, 'config.json'))

// Must match the exact path a FileSystemAdapter({ baseDir: dataDir, namespace:
// 'reminders' }) uses for the key "reminders" — see file-tools-mcp-server.mjs's
// doc comment — so the claude-cli backend's MCP subprocess and this process's
// own reminderStore (below) read/write the same file instead of two disconnected
// reminder lists. FileSystemAdapter's path formula is `${baseDir}/${namespace}/${sanitize(key)}.json`,
// and "reminders" sanitizes to itself (no special characters).
const defaultRemindersFile = join(defaultDataDir, 'reminders', 'reminders.json')

// Env vars still win over persisted config — see cli-config.ts's envOverridesFromProcessEnv
// and config.ts's resolveConfig — so this stays a behavior-preserving migration for anyone
// who already sets ASSISTANT_ENABLE_WEB etc. and never touches /config.
const defaultEnvOverrides = envOverridesFromProcessEnv(process.env)

const defaultNonInteractiveApprovalMode = resolveNonInteractiveApprovalMode(process.env)

// create() only supplies a default for storage the caller didn't already pass in (and falls
// back to in-memory outside a browser) — passing this explicit, filesystem-backed store is
// what gives the CLI real persistence across runs. See the internal plan Phase 3.
const defaultBackend = createNodeFsBackend()

/**
 * Builds the SendEmail transport for an approved `send_email` action, or undefined when email
 * isn't fully configured (validateConfig already rejects `enableEmail` without a usable transport,
 * so in practice this only returns undefined when `enableEmail` is off). The model never reaches
 * this — it only ever proposes; delivery happens here after approval.
 */
function buildEmailSender(config: AssistantConfig): SendEmail | undefined {
  if (!config.enableEmail || !config.emailFrom) return undefined
  if (config.emailProvider === 'smtp' && config.smtpHost && config.smtpPort) {
    return createSmtpSender({
      host: config.smtpHost,
      port: config.smtpPort,
      auth: config.smtpUser && config.smtpPass ? { user: config.smtpUser, pass: config.smtpPass } : undefined,
      from: config.emailFrom,
    })
  }
  if (config.emailProvider === 'resend' && config.resendApiKey) {
    return createResendSender({ apiKey: config.resendApiKey, from: config.emailFrom })
  }
  return undefined
}

/**
 * Picks the ILLMClient for config.llmBackend — one branch per backend, shared in shape with
 * chat-ui's App.tsx createLlmClient() (both switch over the same 5 values), but this one stays
 * CLI-only: claude-cli here is a real node:child_process subprocess (ClaudeCliLLMClient), not
 * the Tauri-bridged equivalent chat-ui's desktop build uses, and it's the only backend always
 * available on this surface (no "unsupported on this platform" branch needed, unlike a plain
 * browser tab which can't spawn `claude` at all).
 */
function buildLlmClient(config: AssistantConfig, workspaceRoot: string, remindersFile: string): ILLMClient {
  switch (config.llmBackend) {
    case 'claude-cli':
      return new ClaudeCliLLMClient({
        fileTools: { workspaceRoot },
        remindersFile,
        shellTools: config.enableShell ? { workspaceRoot } : undefined,
        webTools: config.enableWeb ? { braveApiKey: config.braveApiKey as string | undefined } : undefined,
        actionTools: config.enableEmail ? { workspaceRoot } : undefined,
      })
    case 'anthropic':
      return new AnthropicLLMClient({ apiKey: config.apiKey ?? '' })
    case 'openai':
      return new OpenAICompatibleLLMClient({ apiKey: config.apiKey ?? '', baseUrl: OPENAI_BASE_URL, defaultModel: OPENAI_DEFAULT_MODEL })
    case 'openrouter':
      return new OpenAICompatibleLLMClient({
        apiKey: config.apiKey ?? '',
        baseUrl: OPENROUTER_BASE_URL,
        defaultModel: OPENROUTER_DEFAULT_MODEL,
        extraHeaders: OPENROUTER_EXTRA_HEADERS,
      })
    case 'proxy':
      return new LLMClient({ proxyUrl: config.proxyUrl, authToken: config.authToken })
  }
}

/**
 * Builds a fresh PersonalAssistant (and the llmClient/search function it depends on) from a
 * resolved AssistantConfig — called once at startup and again after any /config change that
 * takes effect, so nothing requires a process restart. Reuses the same dataDir-backed stores
 * each time, so transcripts/experience/checkpoints/reminders carry over across a rebuild.
 */
interface BuildAssistantDeps {
  backend: FsBackend
  dataDir: string
  remindersFile: string
}

async function buildAssistant(config: AssistantConfig, { backend, dataDir, remindersFile }: BuildAssistantDeps): Promise<PersonalAssistant> {
  const workspaceRoot = config.workspaceRoot ?? process.cwd()
  const search = (query: string) => braveSearch(query, config.braveApiKey as string)

  // `search` above is the proxy backend's injected web_search implementation (its manual
  // tool loop calls it directly). The claude-cli backend can't take an injected function —
  // its tools run inside the `claude -p` subprocess — so buildLlmClient passes the same
  // Brave key through to the file-tools MCP server as env instead. Either way, `enableWeb`
  // now wires web_search on both backends.
  const llmClient = buildLlmClient(config, workspaceRoot, remindersFile)

  return PersonalAssistant.create({
    llmClient,
    model: config.model,
    // config.activeProject (set via /project <name>) overrides the default of "the workspace
    // I'm running in" — see PersonalAssistantOptions.activeProject's doc comment.
    activeProject: config.activeProject || workspaceRoot,
    memoryBudgetChars: config.memoryBudgetChars,
    memoryWriteMode: config.memoryWriteMode,
    // M5: consolidation proposals are staged for /memory consolidate; the CLI has the controls, so it may raise them on /new.
    consolidateOnNewSession: true,
    memory: new FileSystemAdapter({ backend, baseDir: dataDir, namespace: 'transcripts' }),
    experienceStore: await FileSystemExperienceStore.create({ backend, baseDir: dataDir, namespace: 'experience' }),
    checkpointStore: new FileSystemAdapter({ backend, baseDir: dataDir, namespace: 'checkpoints' }),
    reminderStore: new InMemoryReminderStore(new FileSystemAdapter({ backend, baseDir: dataDir, namespace: 'reminders' })),
    fileTools: { backend, workspaceRoot },
    webTools: config.enableWeb ? { search } : undefined,
    // executeCommand is the real child_process.spawn-based implementation (shell-executor.ts) —
    // wired in here, not inside assistant.ts, so the browser build never needs node:child_process.
    shellTools: config.enableShell
      ? { backend, workspaceRoot, timeoutMs: config.shellTimeoutMs, networkAllowlist: config.shellNetworkAllowlist, executeCommand: runApprovedShellCommand }
      : undefined,
    // The Resend/SMTP transport is wired in here, not inside assistant.ts, so the browser build
    // never needs nodemailer or a mail server — same split as shellTools' executeCommand.
    actionTools: (() => {
      const sendEmail = buildEmailSender(config)
      return sendEmail ? { backend, workspaceRoot, sendEmail } : undefined
    })(),
    dangerouslySkipPermissions: config.dangerouslySkipPermissions,
    spendCap:
      config.sessionCostLimitUsd !== undefined || config.sessionCallLimit !== undefined
        ? { sessionCostLimitUsd: config.sessionCostLimitUsd, sessionCallLimit: config.sessionCallLimit }
        : undefined,
    // Resolved through the shared config seam (cli-config.ts's envOverridesFromProcessEnv reads
    // ASSISTANT_ONE_LOOP into config.oneLoopMode; /config set oneLoopMode persists it) so the CLI,
    // chat-ui, and the Tauri desktop build all decide this the same way. Undefined here means
    // PersonalAssistant falls back to DEFAULT_ONE_LOOP_MODE.
    oneLoopMode: config.oneLoopMode,
    layerPolicyMode: config.layerPolicyMode,
    // R7: turn-end next-step options and DONE-thread suggestions. Undefined config means the
    // package default (enabled); PersonalAssistant itself defaults to disabled, so this is where
    // the front end opts in.
    goalGraphSuggestMode: isGoalGraphSuggestEnabled(config.goalGraphSuggestMode) ? 'enabled' : 'disabled',
    // P11 of the internal plan — resolved through the same shared config
    // seam as oneLoopMode above (ASSISTANT_PLAN_MODE / `/config set planMode`). Undefined here
    // means PersonalAssistant falls back to DEFAULT_PLAN_MODE ('legacy').
    planMode: config.planMode,
    ambiguityGuardMode: config.ambiguityGuardMode,
  })
}

/**
 * One choice in a structured multi-option prompt (Phase 7 of the internal plan
 * — the numbered/arrow-key approval selector). `key` is both the single-character shortcut shown
 * inline next to the option and the value `askSelect` resolves with; callers order options with
 * the safe/fail-closed choice last, matching `askYesNo`'s own "no real answer → treat as declined"
 * convention (see `askSelect`'s default implementation below, and `ink-select-prompt.tsx`'s
 * `SelectPrompt`, which renders this same list with arrow-key highlight + per-key shortcuts).
 */
export interface SelectOption {
  key: string
  label: string
}

export interface RunCliOptions {
  /**
   * The Ink shell's seam for `/plan graph` (planGraphMode enabled): called with the drawable nodes to open the
   * full-screen pane. Without it (plain REPL, piped input) `/plan graph` prints one static render instead.
   */
  openPlanGraph?: (nodes: VizNode[]) => void
  /** Live per-task statuses from a running turn, forwarded for the open plan graph pane. */
  onPlanProgress?: (tasks: { id: string; status: TaskStatus }[]) => void
  dataDir?: string
  configStore?: ConfigStore
  backend?: FsBackend
  remindersFile?: string
  envOverrides?: Partial<AssistantConfig>
  nonInteractiveApprovalMode?: NonInteractiveApprovalMode
  input?: NodeJS.ReadableStream
  output?: NodeJS.WritableStream
  /**
   * Bypasses buildAssistant()'s config-driven backend selection entirely — the seam tests use
   * to hand runCli a PersonalAssistant wired to a scripted ILLMClient (same pattern as
   * assistant.test.ts) for deterministic command-dispatch/approval-flow coverage. When set, a
   * /config change that would otherwise rebuild the assistant leaves this instance in place.
   */
  assistant?: PersonalAssistant
  /** Overrides the rl.question-based approval prompt — lets tests script approve/decline answers without faking stdin/a real TTY. */
  askYesNo?: (question: string) => Promise<boolean>
  /** Overrides the rl.question-based free-text prompt the clarification sub-loop uses for option numbers, edit notes, and "Other" free text — lets tests script a multi-step answer without faking stdin/a real TTY. */
  askLine?: (question: string) => Promise<string>
  /** Overrides the rl.question-based structured multi-option prompt (Phase 7's approval selector) — lets tests script a selection by key without faking stdin/a real TTY. Resolves with the chosen `SelectOption.key`. */
  askSelect?: (question: string, options: SelectOption[]) => Promise<string>
  /** Test seam: skip the interactive first-run setup regardless of TTY state (also implied when `assistant` is passed). */
  skipFirstRunSetup?: boolean
  /** Test seam: script the first-run setup's line reads. */
  firstRunAsk?: (question: string) => Promise<string>
  /** Test seam: stub the live API-key check in the first-run setup (defaults to a real call to the provider). */
  firstRunTestKey?: (backend: KeyedBackend, key: string) => Promise<KeyTestResult>
}

export interface CliInstance {
  /** Parses and dispatches one line of input exactly as the REPL's 'line' handler does (same dispatchQueue serialization) — the seam cli.test.ts drives command dispatch through without a live TTY. */
  dispatchLine(line: string): Promise<void>
  close(): void
  /**
   * Additive, read-only accessor for the pinned-input TUI shell's status line
   * (the internal plan Phase 3) — the same two signals
   * printStatus() already renders as part of `/status` (lastPlanStatus !== undefined,
   * spendCapStatusLine()), just exposed here instead of only printed. Returns short indicator
   * strings in priority order; empty when there's nothing to report. Not used by the ordinary
   * readline REPL or by non-interactive/piped mode — only the TUI shell polls this.
   */
  getStatusIndicators(): Promise<string[]>
  /** Read-only: the plan graph's drawable nodes (with `live` statuses overlaid), or undefined when planGraphMode is disabled or there is no plan. Feeds the TUI's open plan graph pane. */
  getPlanGraphNodes(live?: { id: string; status: TaskStatus }[]): Promise<VizNode[] | undefined>
}

/**
 * The CLI's REPL, parameterized so cli.test.ts can import and drive it directly instead of only
 * through a live process (see non-interactive-mode.ts's doc comment for why that mattered before
 * this export existed — this is T1's answer to it). `main()` below calls this with no options,
 * getting exactly today's behavior; every option here has a real-filesystem/real-stdio default.
 */
export async function runCli(options: RunCliOptions = {}): Promise<CliInstance> {
  // Printed before anything else — including first-run setup — so it's the very first thing a
  // new or returning user sees, on every surface runCli() drives (plain REPL, piped/scripted
  // input, and the Ink TUI shell, which captures this same console.log via startCapture — see
  // tui-app.ts's own comment on why the banner isn't duplicated there).
  console.log('Aielia is alpha software — expect rough edges and breaking changes. It uses AI models and can make mistakes; verify anything important.\n')

  const dataDir = options.dataDir ?? defaultDataDir
  const configStore = options.configStore ?? defaultConfigStore
  const backend = options.backend ?? defaultBackend
  const remindersFile = options.remindersFile ?? defaultRemindersFile
  const envOverrides = options.envOverrides ?? defaultEnvOverrides
  const nonInteractiveApprovalMode = options.nonInteractiveApprovalMode ?? defaultNonInteractiveApprovalMode

  const inputStream = options.input ?? process.stdin
  const outputStream = options.output ?? process.stdout

  let persisted = await configStore.load()
  let { config, overriddenKeys } = resolveConfig(persisted, envOverrides)
  // The layers' AUDIT_* flags are the single source each layer reads, so the saved /layers choices are written onto process.env
  // (a flag the operator already set stays and is reported pinned). Re-run after every config change.
  let layerPins = applyLayerSettings(sanitizeLayerChoices(config.layers), process.env).pinned

  // First run with nothing configured: offer a one-line setup rather than
  // silently starting on the proxy backend against a proxy that isn't running.
  if (!options.skipFirstRunSetup && !options.assistant) {
    const isInteractive = (inputStream as NodeJS.ReadStream).isTTY === true
    let setupRl: ReturnType<typeof createInterface> | undefined
    const firstRunAsk =
      options.firstRunAsk ??
      ((question: string) => {
        setupRl ??= createInterface({ input: inputStream, output: outputStream })
        return new Promise<string>((resolvePrompt) => {
          setupRl!.question(question, (answer) => resolvePrompt(answer.trim()))
        })
      })
    try {
      persisted = await maybeRunFirstRunSetup({
        configStore,
        persisted,
        overriddenKeys,
        isInteractive,
        ask: firstRunAsk,
        log: (line) => outputStream.write(`${line}\n`),
        testKey: options.firstRunTestKey ?? ((backend, key) => testApiKey(backend, key)),
      })
    } finally {
      setupRl?.close()
    }
    ;({ config, overriddenKeys } = resolveConfig(persisted, envOverrides))
    layerPins = applyLayerSettings(sanitizeLayerChoices(config.layers), process.env).pinned
  }

  try {
    validateConfig({}, config)
  } catch (err) {
    if (!(err instanceof ConfigValidationError)) throw err
    console.error(err.message)
    process.exit(1)
  }

  // Checked before anything else starts, not lazily at the first approval prompt — a session
  // that ran tool calls for several turns before hitting a HIGH-risk gate would otherwise fail
  // deep in, with no chance to recover the work already done, instead of failing immediately
  // with a clear explanation of what to do about it.
  if (nonInteractiveApprovalMode === 'require-tty' && !process.stdin.isTTY) {
    console.error(
      'ASSISTANT_NON_INTERACTIVE_APPROVAL=require-tty is set, but stdin is not a real TTY ' +
        '(piped/scripted input). Refusing to start rather than fail confusingly at the first ' +
        'approval prompt — see README.md\'s "Non-interactive / scripted use" section for the ' +
        'alternative (ASSISTANT_NON_INTERACTIVE_APPROVAL=decline).',
    )
    process.exit(1)
  }

  let assistant = options.assistant ?? (await buildAssistant(config, { dataDir, backend, remindersFile }))

  const rl = createInterface({ input: options.input ?? process.stdin, output: options.output ?? process.stdout, prompt: 'you> ' })
  // Paused immediately, synchronously, before any awaits below get a chance to yield the event
  // loop: createInterface() switches its input stream to flowing mode as soon as it attaches its
  // own internal 'data' listener, so once we hit e.g. the listUndoLogEntries() await further
  // down, a piped/heredoc input whose lines are already fully buffered by the OS gets parsed into
  // 'line' events right then — and since EventEmitter#emit never queues an event for a listener
  // that isn't there yet, every line parsed before rl.on('line', ...) near the bottom of this
  // function runs is silently dropped, not just delayed. rl.prompt() below auto-resumes if
  // paused, but that resume is itself deferred (stream.resume() only schedules a nextTick flow
  // start) and everything from here to the rl.on('line', ...)/rl.resume() pair at the bottom
  // runs synchronously with no further awaits, so the listener is always in place first.
  rl.pause()

  // With no 'SIGINT' listener, readline's own Ctrl+C handling just pauses the interface
  // instead of exiting (see readline's 'SIGINT' event docs) — silently contradicting the
  // startup banner's "Ctrl+C to exit". Registering this listener makes Ctrl+C actually exit.
  rl.on('SIGINT', () => {
    console.log('\nExiting.')
    process.exit(0)
  })

  // Display-only defaults, mirroring each backend's own fallback so the banner shows the
  // model that will actually be used even when config.model is unset — not authoritative
  // (each llmClient picks its own default independently), but sourced from the same
  // @buildaharness/runtime constants those clients use so the banner can't drift from them.
  const backendDisplayModel: Record<AssistantConfig['llmBackend'], string> = {
    proxy: ANTHROPIC_DEFAULT_MODEL,
    'claude-cli': '(your Claude Code default)',
    anthropic: ANTHROPIC_DEFAULT_MODEL,
    openai: OPENAI_DEFAULT_MODEL,
    openrouter: OPENROUTER_DEFAULT_MODEL,
  }
  console.log(`backend: ${config.llmBackend} (${config.model ?? backendDisplayModel[config.llmBackend]})`)

  // No silent default: capabilities only appear in the banner when actually configured,
  // so the banner never implies something is available that isn't.
  const enabledCapabilities: string[] = []
  if (config.enableWeb) enabledCapabilities.push('web search/fetch (brave)')
  if (config.enableShell) enabledCapabilities.push(`shell commands (${config.dangerouslySkipPermissions ? 'NOT approval-gated' : 'approval-gated'})`)
  const capabilitySuffix = enabledCapabilities.length > 0 ? ` — enabled: ${enabledCapabilities.join(', ')}` : ''
  // Loud and separate from the capability list above (which is easy to skim past) —
  // this changes the trust model for every HIGH-risk action, not just shell.
  const dangerBanner = config.dangerouslySkipPermissions
    ? '\n⚠ dangerouslySkipPermissions is ON — every approval prompt (risky messages, file writes, shell commands) is skipped automatically.\n'
    : ''
  // Same "never silently in effect" reasoning as dangerBanner above — the opposite trust
  // direction (declines instead of skips), but just as important to surface up front.
  const nonInteractiveBanner =
    nonInteractiveApprovalMode === 'decline'
      ? '\nASSISTANT_NON_INTERACTIVE_APPROVAL=decline is set — every approval prompt auto-declines.\n'
      : ''

  // The undo-log persists across sessions (it's on disk under the workspace, not in-memory) —
  // surfaced here so a user doesn't discover leftover revertible actions from a prior session
  // only by happening to run /undo-action or /status (T6).
  const startupUndoLogEntries = await assistant.listUndoLogEntries()
  const undoableFromBefore = startupUndoLogEntries.filter((e) => e.undoable).length
  const undoBanner =
    undoableFromBefore > 0
      ? `\n${undoableFromBefore} action${undoableFromBefore === 1 ? '' : 's'} from earlier sessions ${undoableFromBefore === 1 ? 'is' : 'are'} still revertible — see /undo-action.\n`
      : ''

  console.log(`Aielia — your personal assistant on the 11-layer harness, one turn at a time. Ctrl+C to exit.${capabilitySuffix}\n${dangerBanner}${nonInteractiveBanner}${undoBanner}`)
  console.log('Type /help to see all commands, /config to view settings.\n')
  // M5: session start consolidates what earlier sessions left. Background, fail-open, a no-op unless AUDIT_MEMORY_CONSOLIDATION is on.
  void assistant.proposeMemoryConsolidation('cli').catch(() => undefined)
  rl.prompt()

  let lastTrace: AssistantTrace | undefined
  let lastSources: AssistantSource[] | undefined
  let lastPlanStatus: AssistantTurnResult['planStatus']
  // A whole-plan approval that was staged but not yet resolved (status 'needs_plan_approval') —
  // kept so the /plan approve|decline|edit commands can resolve it after the turn has already
  // returned control to the prompt. Cleared the moment a decision is dispatched. Without this,
  // a staged plan had no way to be approved or declined at all from the CLI (chat-ui's
  // PlanApprovalCard + its handlers were the only surface that could resolve one).
  let pendingPlanApproval: { id: string; message: string; snapshot: AssistantTurnResult['planApproval'] } | undefined
  let lastTurnUsage: TokenUsage | undefined
  // Tool calls made by the most recent turn — used only so /undo can warn about a real
  // side effect (e.g. a created reminder) it's about to claim to have removed but can't
  // actually reverse. Reset at the start of every handleTurn call, see writeToolStep below.
  let lastTurnToolSteps: AssistantToolStep[] = []
  // Set whenever the last turn was blocked on an approval gate (message-level risk or a
  // staged write/shell command) and then declined, or escalated — lastTrace stays whatever it
  // was before in either case (neither path ever runs the harness), so without this /why and
  // /layers would fall back to the generic "nothing to explain yet, or it took the fast path"
  // message even right after a real, user-visible decline. That reads as if nothing happened,
  // when something very much did. Cleared whenever a turn actually produces a trace, and on /new.
  let lastNoTraceReason: string | undefined

  // Phase 7's "don't ask again" option, session-scoped only (reset on every process start, never
  // written to `configStore`). `tool-policy.ts`'s `ControlState` (the harness's own per-turn
  // permission/escalation resolver) was checked as the natural home for this and rejected: it's
  // recomputed fresh from world-model evidence every turn with no persisted-preference field at
  // all, so wiring a durable "remembered" flag through it would mean inventing new cross-turn
  // state inside a module that's deliberately a pure, stateless decision function today. A plain
  // in-memory Set scoped to this `runCli()` closure gets the same "stop asking me this" behavior
  // Codex/Claude Code's own selector offers, without that architectural change — at the cost of
  // not surviving a restart, which matches this being explicitly a per-session convenience, not a
  // durable trust decision. Keyed coarsely (pendingActionKind / riskLevel), not per fine-grained
  // command pattern — a finer key would need the same new persisted-state work this deliberately
  // avoids.
  const rememberedActionKinds = new Set<string>()
  const rememberedRiskLevels = new Set<string>()

  /** The three choices every approval prompt offers (Phase 7) — "No" last, so `askSelect`'s fail-closed fallback (no real answer read) always resolves to declining, never approving. */
  const APPROVAL_OPTIONS: SelectOption[] = [
    { key: 'y', label: 'Yes' },
    { key: 'a', label: "Yes, don't ask again this session" },
    { key: 'n', label: 'No' },
  ]

  /** claude-cli is the only backend that returns a real dollar cost (--output-format json's total_cost_usd) — every other backend (proxy, and now anthropic/openai/openrouter, none of which surface billing via TokenUsage.costUsd) gets an approximate estimate instead, see model-pricing.ts. */
  function withCostEstimate(usage: TokenUsage): TokenUsage {
    if (config.llmBackend === 'claude-cli' || usage.costUsd !== undefined) return usage
    const estimated = estimateCostUsd(config.model ?? ANTHROPIC_DEFAULT_MODEL, usage)
    return estimated !== undefined ? { ...usage, costUsd: estimated } : usage
  }

  const PLAN_TASK_STATUS_ICON: Record<string, string> = {
    PENDING: '○', RUNNING: '▶', COMPLETE: '✓', FAILED: '✗', BLOCKED: '✗', HUMAN_REQUIRED: '~',
  }

  function printPlan(): void {
    if (!lastPlanStatus) {
      console.log('\nNo active plan for this session.\n')
      return
    }
    // Phase 6 of the CLI formatting plan ("distinct plan-mode UI") — one combined console.log
    // call, prefixed with PLAN_LINE_PREFIX, so the TUI's classifyLineKind (tui-app.tsx) renders
    // the whole block as a single bordered PlanBox instead of plain 'system' text one line at a
    // time. Prefix goes on its own leading line (stripped for display, same convention as
    // ASSISTANT_REPLY_PREFIX) rather than glued onto "Plan: …" so it can never visually collide
    // with real plan content. The plain (non-TUI) CLI path also goes through this same
    // console.log call — startCapture's classify() there just emits the marker line as-is; the
    // TUI-specific stripping never runs, and the marker glyph is unusual enough not to be
    // mistaken for real output outside the TUI, matching how ASSISTANT_REPLY_PREFIX already
    // behaves in non-TUI mode.
    const lines = [
      PLAN_LINE_PREFIX,
      `Plan: ${lastPlanStatus.templateName ?? 'custom plan'} (${lastPlanStatus.completionPct.toFixed(1)}% complete)`,
      ...lastPlanStatus.tasks.flatMap((task) => [
        `  ${PLAN_TASK_STATUS_ICON[task.status] ?? '?'} [${task.status}] ${task.id} — ${task.description}`,
        ...(task.note ? [`      not accepted as done: ${task.note}`] : []),
      ]),
      `Success criteria: ${lastPlanStatus.successCriteria}`,
    ]
    console.log(`\n${lines.join('\n')}\n`)
  }

  /**
   * P9 of the internal plan — `/plan sketch <request>` invokes the
   * lightweight plan-sketch delegate (PersonalAssistant.sketchPlan): one bounded, advisory LLM
   * call that prints a proposed task list directly, with no approve/decline controls (nothing was
   * staged — INV-35) and no effect on `/plan`'s own drafting-plan display above.
   */
  async function handlePlanSketch(args: string[]): Promise<void> {
    const request = args.join(' ').trim()
    if (!request) {
      console.log('\nUsage: /plan sketch <request>\n')
      return
    }
    console.log('\nSketching a plan (read-only grounding only, nothing staged)...\n')
    const result = await assistant.sketchPlan('cli', request)
    // Phase 6 of the CLI formatting plan: this is genuine LLM-authored prose (often markdown —
    // headers, `- [ ]` checklists), not deterministic CLI-controlled text, so it's routed through
    // the same 'Aielia>' marker as an ordinary chat reply rather than left to default-classify as
    // plain 'system' text — the TUI's classifyLineKind (tui-app.tsx) then renders it through the
    // existing assistant-reply markdown path (markdown-line.tsx) instead of printing literal
    // '##'/'- [ ]' characters, the same gap the underlying report flagged for the legacy
    // (DEFAULT_PLAN_MODE) prose path specifically.
    console.log(`Aielia> ${result.reply ?? '(no reply)'}\n`)
    if (result.usage) lastTurnUsage = withCostEstimate(result.usage)
  }

  /**
   * The choices a staged whole-plan approval offers — the CLI counterpart to chat-ui's
   * `PlanApprovalCard` buttons, resolved through the exact same `PlanApprovalService`. `'d'`
   * ("decide later") is CLI-specific: unlike the action-approval prompt above, a plan is a
   * document worth reading before signing off, so returning control to the REPL (with the
   * /plan approve|edit|decline commands) beats forcing an answer under the prompt. `'n'` (Decline)
   * stays last so `askSelect`'s fail-closed fallback can only ever decline, never approve.
   */
  const PLAN_APPROVAL_OPTIONS: SelectOption[] = [
    { key: 'y', label: 'Approve' },
    { key: 'e', label: 'Approve with edits' },
    { key: 't', label: 'Approve & trust this plan (its write/shell steps stop re-prompting)' },
    { key: 'd', label: 'Decide later — /plan approve|edit|decline' },
    { key: 'n', label: 'Decline' },
  ]

  /** Renders a plan staged for approval — same PLAN_LINE_PREFIX-wrapped single console.log as printPlan, so the TUI's classifyLineKind (tui-app.tsx) draws it as one bordered PlanBox. */
  function printPlanApproval(snapshot: NonNullable<AssistantTurnResult['planApproval']>): void {
    const lines = [
      PLAN_LINE_PREFIX,
      `Plan ready for approval${snapshot.templateName ? `: ${snapshot.templateName}` : ' (custom plan)'}`,
      `Success criteria: ${snapshot.successCriteria}`,
      ...(snapshot.rationale ? [`Why: ${snapshot.rationale}`] : []),
      ...snapshot.tasks.map((task) => `  ${task.riskLevel === 'HIGH' ? '!' : task.riskLevel === 'MEDIUM' ? '·' : '○'} [${task.riskLevel ?? 'LOW'}] ${task.id} — ${task.description}`),
      ...(snapshot.reviewNotes && snapshot.reviewNotes.length > 0
        ? ['Review notes:', ...snapshot.reviewNotes.map((note) => `  - ${note}`)]
        : []),
    ]
    console.log(`\n${lines.join('\n')}\n`)
  }

  /**
   * Reads the "approve with edits" payload — the CLI counterpart to `PlanApprovalCard`'s
   * checkbox-cancel + inline-edit controls, the only other surface that builds `PlanApprovalEdits`.
   * Unknown task ids are dropped here (with a warning) rather than passed through:
   * `resolvePendingPlanApproval` throws on an unrecognized id and fails the whole approval closed,
   * so a single typo would otherwise re-stage the plan with a bare "couldn't apply" reason.
   */
  async function promptPlanEdits(snapshot: NonNullable<AssistantTurnResult['planApproval']>): Promise<PlanApprovalEdits> {
    const knownIds = new Set(snapshot.tasks.map((task) => task.id))
    const cancelRaw = await askLine('Task ids to cancel (comma-separated, blank for none): ')
    const editRaw = await askLine('Edits as "id=new description" pairs separated by ";", e.g. t2=Reword this. (blank for none): ')
    const cancelTaskIds = cancelRaw.split(/[\s,]+/).map((s) => s.trim()).filter(Boolean)
    const parsedEdits = editRaw
      .split(';')
      .map((pair) => pair.trim())
      .filter(Boolean)
      .map((pair) => {
        const sep = pair.indexOf('=')
        return sep >= 0 ? { id: pair.slice(0, sep).trim(), description: pair.slice(sep + 1).trim() } : { id: pair, description: '' }
      })
    const validCancels = cancelTaskIds.filter((id) => knownIds.has(id))
    const validEdits = parsedEdits.filter((edit) => knownIds.has(edit.id) && edit.description)
    const unknown = [...cancelTaskIds.filter((id) => !knownIds.has(id)), ...parsedEdits.filter((e) => !knownIds.has(e.id)).map((e) => e.id)]
    if (unknown.length > 0) console.log(`  [ignoring unknown task id(s): ${[...new Set(unknown)].join(', ')}]`)
    return {
      ...(validCancels.length > 0 ? { cancelTaskIds: validCancels } : {}),
      ...(validEdits.length > 0 ? { editedTasks: validEdits } : {}),
    }
  }

  /**
   * `/plan approve|trust|edit|decline` — resolves the plan stashed by the `needs_plan_approval`
   * branch of handleTurn (the "decide later" path), re-entering the ordinary turn pipeline with
   * the same originating message so an approve runs the now-active plan's first task exactly the
   * way a freshly template-matched plan would.
   */
  async function handlePlanApprovalCommand(sub: string): Promise<void> {
    if (!pendingPlanApproval) {
      console.log('\nNo plan is awaiting approval.\n')
      return
    }
    const { id, message, snapshot } = pendingPlanApproval
    let decision: PlanDecision
    let edits: PlanApprovalEdits | undefined
    if (sub === 'approve') {
      decision = 'approve'
    } else if (sub === 'trust') {
      decision = 'approve_trusted'
    } else if (sub === 'edit') {
      if (!snapshot) {
        console.log('\n[tasks unavailable for editing — /plan approve or /plan decline]\n')
        return
      }
      printPlanApproval(snapshot)
      edits = await promptPlanEdits(snapshot)
      decision = 'approve_with_edits'
    } else {
      decision = 'decline'
    }
    pendingPlanApproval = undefined
    lastTrace = undefined
    lastNoTraceReason = `No harness trace — the last turn staged a plan that was ${decision === 'decline' ? 'declined' : 'approved'} before the harness ran.`
    await handleTurn(message, false, undefined, undefined, undefined, id, decision, edits)
  }

  /** The plan graph's nodes (live statuses overlaid), optionally narrowed to one goal thread; undefined when there is nothing to draw. */
  async function loadPlanGraphNodes(live?: { id: string; status: TaskStatus }[], threadId?: string): Promise<VizNode[] | undefined> {
    const record = await assistant.getPlanGraph('cli')
    if (!record) return undefined
    let nodes = planToSnapshot(record, live ?? []).nodes
    if (threadId) nodes = nodes.filter((n) => n.id.startsWith(`${threadId}__`))
    return nodes.length ? nodes : undefined
  }

  /** `/plan graph [thread-id]` — read-only plan graph. TUI: opens the pane. Plain CLI: one static render at the terminal width (checklist when it cannot be drawn). */
  async function handlePlanGraph(args: string[]): Promise<void> {
    const nodes = await loadPlanGraphNodes(undefined, args[0])
    if (!nodes) {
      console.log(args[0] ? `\nNo plan graph for thread "${args[0]}".\n` : '\nNo active plan for this session.\n')
      return
    }
    if (options.openPlanGraph) {
      const probe = renderPlan(nodes, { maxCols: 80 })
      if (probe.ok) {
        options.openPlanGraph(nodes)
        return
      }
      console.log(`\n[plan graph unavailable: ${probe.message}] showing the checklist instead.`)
      printPlan()
      return
    }
    const cols = process.stdout.columns || 80
    const color = Boolean(process.stdout.isTTY) && !process.env.NO_COLOR
    const result = renderPlan(nodes, { maxCols: cols, color })
    if (!result.ok) {
      console.log(`\n[plan graph unavailable: ${result.message}] showing the checklist instead.`)
      printPlan()
      return
    }
    if (!result.fits) {
      console.log(`\n[plan graph is wider than ${cols} columns] dependency list:\n`)
      for (const n of nodes) console.log(`  [${n.status}] ${n.id} — ${n.label}${n.deps.length ? `  (after: ${n.deps.join(', ')})` : ''}`)
      console.log('')
      return
    }
    console.log(`\n${result.lines.join('\n')}\n`)
  }

  async function handlePlan(args: string[]): Promise<void> {
    const sub = args[0]
    if (sub === 'graph' && isPlanGraphEnabled(config.planGraphMode)) {
      await handlePlanGraph(args.slice(1))
      return
    }
    if (sub === 'sketch') {
      await handlePlanSketch(args.slice(1))
      return
    }
    if (sub === 'approve' || sub === 'trust' || sub === 'edit' || sub === 'decline') {
      await handlePlanApprovalCommand(sub)
      return
    }
    // A plan staged for approval is what "/plan" should show while it's pending — the
    // "Decide later — /plan to review" option points here. lastPlanStatus isn't set on a
    // needs_plan_approval turn (the branch returns before the ordinary render), so without this
    // /plan would show the previous plan or "No active plan" instead of the draft awaiting a decision.
    if (pendingPlanApproval?.snapshot) {
      printPlanApproval(pendingPlanApproval.snapshot)
      return
    }
    printPlan()
  }

  function verificationHealthLabel({ strength, feasibility }: AssistantTrace['verificationHealth']): string {
    const confidence = Math.min(strength, feasibility)
    if (confidence >= 0.7) return 'High confidence'
    if (confidence >= 0.4) return 'Reasonably confident'
    return 'Worth double-checking'
  }

  /** One-line summary of AssistantTrace.batchBudget — the same found/not_found/truncated_while_productive
   * counts a batch turn's synthesized reply is already built from, just as a glance-able tally
   * rather than prose. Shared by /why's compact view and /layers' fuller per-item breakdown. */
  function batchBudgetSummaryLine(batchBudget: NonNullable<AssistantTrace['batchBudget']>): string {
    const found = batchBudget.perItemOutcomes.filter((o) => o.status === 'found').length
    const notFound = batchBudget.perItemOutcomes.filter((o) => o.status === 'not_found').length
    const truncated = batchBudget.perItemOutcomes.filter((o) => o.status === 'truncated_while_productive').length
    return (
      `Batch: ${batchBudget.itemCount} items — ${found} found, ${notFound} not found, ${truncated} truncated ` +
      `(${batchBudget.totalCallsUsed} calls used, projected ~${Math.ceil(batchBudget.projectedTotal)})`
    )
  }

  function printWhy(): void {
    // What the reply could have known (M6): printed with or without a harness trace, since a fast-path turn still saw memory.
    const memoryLine = formatMemoryInjection(assistant.getLastMemoryInjection())
    if (!lastTrace) {
      console.log(`\n${lastNoTraceReason ?? 'No harness trace for the last turn (nothing to explain yet, or it took the fast path).'}\n${memoryLine}\n`)
      return
    }
    console.log(`\n${verificationHealthLabel(lastTrace.verificationHealth)}`)
    // Only the layers that actually fired, chained in the order they fired — quiet otherwise
    // (Design Principle 3 of the harness layer activation plan: the common, unremarkable case
    // stays quiet, matching the existing "don't badge LOW risk" convention). Use /layers for
    // the full fired/skipped picture across all 11.
    const chain = buildWhyChain(lastTrace.layerActivity)
    if (chain.length > 0) {
      console.log('  ' + chain.map((item) => `${LAYER_SHORT_CODE[item.layer]} (${item.reason})`).join(' > '))
    }
    // Absent on every non-batch turn (see AssistantTrace.batchBudget's doc comment) — only a
    // batch-research turn ever has this to show.
    if (lastTrace.batchBudget) {
      console.log('  ' + batchBudgetSummaryLine(lastTrace.batchBudget))
    }
    console.log(memoryLine)
    console.log('')
  }

  /** Full fired/skipped picture across all 11 harness layers for the last turn — pure text rendering of the same layer_activity data /why's "What I checked" summarizes selectively. */
  function printLayers(): void {
    if (!lastTrace) {
      console.log(`\n${lastNoTraceReason ?? 'No harness trace for the last turn (nothing to explain yet, or it took the fast path).'}\n`)
      return
    }
    console.log('')
    const byLayer = new Map(lastTrace.layerActivity.map((e) => [e.layer, e]))
    for (const layer of LAYER_ORDER) {
      const e = byLayer.get(layer)
      const mark = e?.fired ? '✓' : '·'
      const reason = e?.reason ?? 'not evaluated this turn'
      console.log(`  [${mark}] ${LAYER_DISPLAY_NAME[layer].padEnd(22)} ${reason}`)
    }
    // The full per-item breakdown behind /why's one-line batchBudgetSummaryLine tally — same
    // "absent on every non-batch turn" gating as that summary.
    if (lastTrace.batchBudget) {
      console.log('')
      console.log(`  ${batchBudgetSummaryLine(lastTrace.batchBudget)}`)
      const STATUS_MARK: Record<'found' | 'not_found' | 'truncated_while_productive', string> = {
        found: '✓', not_found: '✗', truncated_while_productive: '~',
      }
      for (const outcome of lastTrace.batchBudget.perItemOutcomes) {
        console.log(`    [${STATUS_MARK[outcome.status]}] ${outcome.item.padEnd(30)} ${outcome.status} (${outcome.callsUsed} calls)`)
      }
    }
    console.log('')
  }

  const SOURCE_TOOL_LABEL: Record<AssistantSource['tool'], string> = {
    read_file: 'Read',
    list_directory: 'Listed',
    web_search: 'Searched',
    fetch_url: 'Fetched',
  }

  function printSources(): void {
    if (!lastSources || lastSources.length === 0) {
      console.log('\nNo sources for the last turn (it used no file/web tool calls).\n')
      return
    }
    console.log('')
    for (const source of lastSources) {
      console.log(`  - ${SOURCE_TOOL_LABEL[source.tool]} ${source.path}`)
    }
    console.log('')
  }

  function printHelp(): void {
    console.log(`\n${formatHelp()}\n`)
  }

  /** Ends the current conversation: clears transcript/facts/plan state and resets local display state so /why, /sources, /plan immediately reflect the fresh session instead of showing stale data. */
  async function handleClear(): Promise<void> {
    await assistant.clearSession('cli')
    lastTrace = undefined
    lastSources = undefined
    lastPlanStatus = undefined
    pendingPlanApproval = undefined
    lastTurnUsage = undefined
    lastNoTraceReason = undefined
    console.log('\n✓ Started a fresh conversation.\n')
  }

  /**
   * Explicit inspect/clear for a stuck harness checkpoint — a scoped alternative to `/clear`
   * (which also wipes transcript/facts/plan) or moving the whole
   * `~/.buildaharness/personal-assistant/` directory aside by hand, previously the only way to
   * recover from a checkpoint that keeps failing to resume (e.g. left behind by a process killed
   * mid-turn — see assistant.ts's runId doc comment). Bare `/checkpoint` inspects without
   * clearing; `/checkpoint clear` clears it, matching `/config`/`/config set`'s own
   * bare-vs-subcommand shape.
   */
  async function handleCheckpoint(args: string[]): Promise<void> {
    if (args[0] === 'clear') {
      const result = await assistant.clearCheckpoint('cli')
      console.log(
        result.cleared
          ? `\n✓ Cleared the stuck checkpoint (was at step ${result.stepsUsed}, node "${result.currentNode}"). Conversation history is untouched — your next message starts a fresh harness run.\n`
          : '\nNo checkpoint to clear — the last turn either completed normally or there was nothing in progress.\n',
      )
      return
    }
    const status = await assistant.getCheckpointStatus('cli')
    if (!status.present) {
      console.log('\nNo checkpoint present — the last turn completed normally or there was nothing in progress.\n')
      return
    }
    const attemptsNote =
      status.failedResumeAttempts > 0
        ? ` — failed to resume ${status.failedResumeAttempts} time${status.failedResumeAttempts === 1 ? '' : 's'} in a row so far`
        : ''
    console.log(
      `\nA checkpoint is present: step ${status.stepsUsed}, last node "${status.currentNode}"${attemptsNote}.\n` +
        `Your next message will try to resume it automatically. Run /checkpoint clear to discard it and start fresh instead.\n`,
    )
  }

  async function printStatus(): Promise<void> {
    const transcript = await assistant.getTranscript('cli')
    const undoLogEntries = await assistant.listUndoLogEntries()
    const spendCapLine = await spendCapStatusLine()
    console.log(
      `\n${formatStatus({ config, overriddenKeys, transcriptLength: transcript.length, planActive: lastPlanStatus !== undefined, undoLogEntries, spendCapLine })}\n`,
    )
  }

  /** Shared by /status and /cost (plan T2 step 5: "not a separate display") — undefined when no ceiling is configured. */
  async function spendCapStatusLine(): Promise<string | undefined> {
    if (config.sessionCostLimitUsd === undefined && config.sessionCallLimit === undefined) return undefined
    const state = await assistant.getSpendState('cli')
    return formatSpendCapStatus(state, { sessionCostLimitUsd: config.sessionCostLimitUsd, sessionCallLimit: config.sessionCallLimit })
  }

  /** Writes the session transcript to a markdown file — an explicit argument overrides the default filename, resolved relative to process.cwd() if not absolute. */
  async function handleExport(args: string[]): Promise<void> {
    const transcript = await assistant.getTranscript('cli')
    if (transcript.length === 0) {
      console.log('\nNothing to export yet.\n')
      return
    }
    const filename = resolvePath(process.cwd(), args[0] ?? defaultExportFilename())
    try {
      await writeFile(filename, formatTranscriptMarkdown(transcript), 'utf-8')
      console.log(`\n✓ Exported ${transcript.length} message${transcript.length === 1 ? '' : 's'} to ${filename}\n`)
    } catch (err) {
      // Mirrors handleTurn's catch convention (below) — a failed write is reported, not thrown.
      const { message } = classifyError(err)
      console.log(`\n[error] ${message}\n`)
    }
  }

  /**
   * Removes the last exchange from conversation history. Only affects what the model
   * remembers — a real write_file/run_shell_command effect from the undone turn is not
   * reversed (see the plan's Known limitations). Peeks at the transcript before calling
   * undoLastTurn so the confirmation message can name which side was removed, without
   * changing undoLastTurn's return shape just for that.
   *
   * create_reminder is the one tool call this reversible-sounding command can silently fail
   * to revert without the user realizing it — reminders need no approval (see risk-classifier.ts),
   * so unlike write_file/run_shell_command there's no prior "Proceed?" prompt that already told
   * the user this was consequential. ReminderStore has no delete/remove method to actually undo
   * it with (adding one is a packages/runtime change, out of scope here), so the best available
   * fix is surfacing the caveat explicitly instead of letting "Removed the last exchange" imply
   * the reminder went away too.
   */
  async function handleUndo(): Promise<void> {
    const transcriptBefore = await assistant.getTranscript('cli')
    if (transcriptBefore.length === 0) {
      console.log('\nNothing to undo.\n')
      return
    }
    const wasPendingApproval = transcriptBefore[transcriptBefore.length - 1].role !== 'assistant'
    const undoneReminders = lastTurnToolSteps.filter((s) => s.tool === 'create_reminder')

    const result = await assistant.undoLastTurn('cli')
    if (!result.undone) {
      console.log('\nNothing to undo.\n')
      return
    }
    // The display state described the now-undone turn — there's no cheap way to recover the
    // exact prior turn's trace/sources without storing turn-scoped snapshots (accepted limitation).
    lastTrace = undefined
    lastSources = undefined
    lastPlanStatus = undefined
    lastTurnToolSteps = []
    const caveat = undoneReminders.length > 0
      ? ` Note: ${undoneReminders.length === 1 ? 'a reminder' : `${undoneReminders.length} reminders`} created in that exchange (${undoneReminders.map((s) => `"${s.input.text}"`).join(', ')}) ${undoneReminders.length === 1 ? 'is' : 'are'} still active — /undo only removes chat history, not that side effect.`
      : ''
    console.log(
      `\n✓ Removed ${wasPendingApproval ? 'the pending message awaiting approval' : 'the last exchange (1 user message, 1 assistant reply)'}.${caveat}\n`,
    )
  }

  /**
   * `/undo-action` with no argument lists real filesystem effects still on record as revertible
   * (T3 step 1). `/undo-action <id>` stages a revert of that entry as its own approval-gated
   * action (T3 step 2) — same "yes/no, then re-call turn() to apply or discard" shape as any
   * other staged write/shell action, except staging itself happens synchronously here (via
   * assistant.stageUndoAction) rather than by the model calling a tool, so the confirmation
   * prompt is driven directly rather than via handleTurn's needs_approval branch.
   */
  async function handleUndoAction(args: string[]): Promise<void> {
    if (args.length === 0) {
      const entries = await assistant.listUndoLogEntries()
      console.log(`\n${formatUndoLogListing(entries)}\n`)
      return
    }

    const staged = await assistant.stageUndoAction(args[0])
    if (staged.status === 'error') {
      console.log(`\n✗ ${staged.message}\n`)
      return
    }

    console.log(`\n[needs approval — revert] ${staged.reason}`)
    const confirmed = await askYesNo('Apply this revert? (y/N) ')
    lastTrace = undefined
    lastNoTraceReason = `No harness trace — the last turn was a staged revert that was ${confirmed ? 'approved' : 'declined'} before the harness ran.`
    await handleTurn('', confirmed, staged.pendingActionId)
  }

  async function printMemory(): Promise<void> {
    const summary = await assistant.getMemorySummary('cli')
    const digests = await assistant.listSessionDigests()
    const digestLine = digests.length > 0 ? `\nSession digests stored: ${digests.length} (/memory forget digest [id] erases them; /memory export includes them).\n` : ''
    console.log(`\n${formatMemoryStatus(await assistant.getMemoryStatus('cli'))}\n\n${formatMemorySummary(summary)}\n${digestLine}`)
  }

  /**
   * `/memory export [file]` — writes the full, unbounded learned-experience contents (every
   * strategy weight/decomposition/recovery sequence, not just the 20-entry preview `/memory`
   * prints) plus facts/reminders to a JSON file. Mirrors handleExport's shape: explicit
   * argument overrides the default filename, resolved relative to process.cwd() if not
   * absolute, a failed write is reported rather than thrown. Read-only over already-persisted
   * data — never an LLM call or network request.
   */
  async function handleMemoryExport(args: string[]): Promise<void> {
    const data = await assistant.exportMemory('cli')
    const filename = resolvePath(process.cwd(), args[0] ?? defaultMemoryExportFilename())
    try {
      await writeFile(filename, formatMemoryExport(data), 'utf-8')
      console.log(`\n✓ Exported learned memory to ${filename}\n`)
    } catch (err) {
      const { message } = classifyError(err)
      console.log(`\n[error] ${message}\n`)
    }
  }

  /** `/memory confirm <n|category>` / `/memory reject <n|category>` — see PersonalAssistant.confirmPendingFact/rejectPendingFact's doc comments for `selector`'s shape. */
  async function handleMemoryPending(action: 'confirm' | 'reject', args: string[]): Promise<void> {
    const selector = args[0]
    if (!selector) {
      console.log(`\nUsage: /memory ${action} <n> or /memory ${action} <category>\n`)
      return
    }
    const outcome = action === 'confirm' ? await assistant.confirmPendingFact(selector) : await assistant.rejectPendingFact(selector)
    console.log(`\n${formatMemoryPendingOutcome(action === 'confirm' ? 'confirmed' : 'rejected', outcome)}\n`)
  }

  /** `/memory forget <n>` — removes an already-durable/session fact by its `/memory` display number. Unlike confirm/reject, there's no category form (see PersonalAssistant.forgetFact's doc comment). */
  async function handleMemoryForget(args: string[]): Promise<void> {
    const selector = args[0]
    if (!selector) {
      console.log('\nUsage: /memory forget <n> [erase]\n')
      return
    }
    const erase = args[1] === 'erase'
    const outcome = await assistant.forgetFact(selector, 'cli', erase)
    const note = outcome.ok && !erase && memoryAuditLogEnabled() ? ' The audit log still holds its text (see /memory history); use `/memory forget <n> erase` to remove that too.' : ''
    console.log(`\n${formatMemoryPendingOutcome('forgotten', outcome)}${note}\n`)
  }

  /** `/memory` with no args shows a preview; `/memory export [file]` writes the full contents to disk (see handleMemoryExport); `/memory confirm|reject <n|category>` resolves a pending-confirmation guess (see handleMemoryPending); `/memory forget <n>` removes an already-learned fact (see handleMemoryForget). */
  async function handleMemory(args: string[]): Promise<void> {
    if (args[0] === 'export') {
      await handleMemoryExport(args.slice(1))
      return
    }
    if (args[0] === 'confirm' || args[0] === 'reject') {
      await handleMemoryPending(args[0], args.slice(1))
      return
    }
    if (args[0] === 'forget' && (args[1] === 'digest' || args[1] === 'digests')) {
      // D4: episodic digests are covered by /memory forget — one by id, or all of them.
      const removed = await assistant.forgetDigests(args[2])
      console.log(`\nForgot ${removed} session digest${removed === 1 ? '' : 's'}.\n`)
      return
    }
    if (args[0] === 'forget') {
      await handleMemoryForget(args.slice(1))
      return
    }
    if (args[0] === 'history') {
      console.log(`\n${formatMemoryHistory(await assistant.memoryHistory())}\n`)
      return
    }
    if (args[0] === 'status') {
      console.log(`\n${formatMemoryStatus(await assistant.getMemoryStatus('cli'))}\n`)
      return
    }
    if (args[0] === 'archive') {
      // One numbered listing (set-aside + replaced entries); `restore` and `forget` index the same list.
      if (args[1] === 'forget') {
        const outcome = await assistant.forgetArchivedFact(args[2] ?? '')
        console.log(`\n${formatMemoryPendingOutcome('forgotten', outcome)}\n`)
        return
      }
      if (args[1] === 'restore') {
        const outcome = await assistant.restoreArchivedMemory(args[2] ?? '', 'cli')
        console.log(`\n${outcome.message}\n`)
        return
      }
      console.log(`\n${formatMemoryArchive(await assistant.listArchivedFacts(), await assistant.restorableArchiveCount())}\n`)
      return
    }
    if (args[0] === 'off' || args[0] === 'on') {
      await assistant.setMemoryEnabled(args[0] === 'on')
      console.log(args[0] === 'off'
        ? '\nMemory writes are OFF for this install: nothing new will be saved (facts, pending guesses, digests). What is already stored stays readable; /memory forget and /memory reject still work. /memory on resumes.\n'
        : '\nMemory writes are on.\n')
      return
    }
    if (args[0] === 'undo') {
      const outcome = await assistant.undoMemoryChange(args[1] ?? '', 'cli')
      console.log(`\n${outcome.message}\n`)
      return
    }
    if (args[0] === 'consolidate') {
      await handleMemoryConsolidate(args.slice(1))
      return
    }
    await printMemory()
  }

  /** `/memory consolidate [accept <n>|dismiss <n>]` — M5. Bare form runs the proposal pass now (forcing the model pass) and lists what is staged; nothing is applied until `accept`. */
  async function handleMemoryConsolidate(args: string[]): Promise<void> {
    if (args[0] === 'accept' || args[0] === 'dismiss') {
      const outcome = args[0] === 'accept' ? await assistant.acceptMemoryProposal(args[1] ?? '', 'cli') : await assistant.dismissMemoryProposal(args[1] ?? '')
      console.log(`\n${outcome.message}\n`)
      return
    }
    // Runs whichever consolidator is registered (PersonalAssistant registers M5's), then lists what is staged.
    const outcome = await assistant.consolidateMemory('cli')
    const proposals = await assistant.memoryProposals()
    if (proposals.length === 0) { console.log(`\n${outcome.message}\n`); return }
    console.log(`\n${outcome.status === 'done' ? '' : `${outcome.message}\n`}Proposed changes (nothing applied yet):\n${proposals.map((p, i) => `  ${i + 1}. [${p.kind}]${p.touchesUserAsserted ? ' (touches something you said yourself)' : ''} ${p.text ? `-> "${p.text}" ` : ''}${p.reason}`).join('\n')}\n  Use /memory consolidate accept <n> or dismiss <n>.\n`)
  }

  /** `/search <query>` — ranked search over past messages (see PersonalAssistant.searchTranscript), never an LLM call or network request. A query with no terms is treated the same as no results, not an error. */
  async function handleSearch(args: string[]): Promise<void> {
    const query = args.join(' ')
    if (!query.trim()) {
      console.log('\nUsage: /search <query>\n')
      return
    }
    const hits = await assistant.searchTranscript(query)
    console.log(`\n${formatSearchResults(hits, query)}\n`)
  }

  /** `/goals` — R5's review surface (see plans/hierarchical_goal_tree_and_steering_plan.html Phase 7): every known goal thread this session, tagged with its visibility bucket. A pure read, same "never an LLM call" discipline as /search — works whether or not goalGraphMode is enabled, since it just shows whatever the session's GoalGraphRecord already holds (empty for a session that never touched goal-thread machinery). */
  async function handleGoals(): Promise<void> {
    const state = await assistant.getGoalGraphState('cli')
    console.log(`\n${formatGoalGraphState(state)}\n`)
  }

  async function printCost(): Promise<void> {
    const spendCapLine = await spendCapStatusLine()
    // Source "This session" from the persisted spend ledger (assistant.getSpendState) — the same
    // cross-turn, cross-/new store the spend-cap line above is drawn from (recordSpend() always
    // updates it, regardless of backend or whether a cap is configured). An earlier version of
    // this tracked tokens separately in an in-process variable that reset on /new and on every
    // fresh CLI process, while the persisted ledger did not — sourcing the two numbers from
    // different scopes used to show e.g. "0 in / 0 out tokens" next to a real nonzero dollar cost
    // once any turn had run before the current /new.
    const spendState = await assistant.getSpendState('cli')
    const session = { inputTokens: spendState.cumulativeInputTokens, outputTokens: spendState.cumulativeOutputTokens, costUsd: spendState.cumulativeCostUsd }
    console.log(`\n${formatCostSummary({ lastTurn: lastTurnUsage, session, backend: config.llmBackend, spendCapLine })}\n`)
  }

  async function handleDoctor(): Promise<void> {
    const workspaceRoot = config.workspaceRoot ?? process.cwd()
    const checks = await Promise.all([
      // Backend-specific checks only run for the backend actually in use — skipped, not
      // reported as failing, for the one that's inactive.
      ...(config.llmBackend === 'proxy' ? [checkProxyHealth(config.proxyUrl)] : []),
      ...(config.llmBackend === 'claude-cli' ? [checkClaudeCli(process.env.CLAUDE_PATH ?? 'claude')] : []),
      checkWorkspaceRoot(workspaceRoot),
      checkDataDirWritable(backend, dataDir),
      ...checkMemoryHealth(await assistant.getMemoryStatus('cli')),
      // Informational only (always ok:true) — surfaces the active backend/flags so a user has
      // one command to confirm config, rather than none (see file's own config summary gap).
      { label: `llmBackend: ${config.llmBackend}`, ok: true },
      { label: `enableShell: ${config.enableShell ?? false}, enableWeb: ${config.enableWeb ?? false}`, ok: true },
      // Provider API keys are stored plaintext in config.json, not an OS keychain — confirming
      // that explicitly here rather than leaving it unstated (no keychain integration exists).
      { label: 'provider keys stored: plaintext in config.json (no OS keychain integration)', ok: true },
    ])
    console.log(`\n${formatDoctorReport(checks)}\n`)
  }

  let lastProgressLineLength = 0
  function writeProgress(progress: AssistantProgress): void {
    // Layer name instead of the raw node id even on a non-plan turn (Phase 3.3: "Step 3/5 —
    // Verification…" reads better than "Step 3/5 — verify…") — falls back to the node's own
    // display name for loop-scaffolding nodes (context_compression etc.) that map to no layer.
    const layer = nodeToLayer(progress.currentNode)
    const label = layer ? LAYER_DISPLAY_NAME[layer] : nodeDisplayName(progress.currentNode)
    // A plan-driven turn gets a plan-aware prefix instead of the generic step counter for the
    // duration of the run (Phase 3.2) — the node/layer name is still shown after it, and full
    // harness-internal detail is still available via /why once the turn finishes.
    const prefix = progress.planPosition
      ? `[${progress.planPosition.templateName ?? 'custom plan'} — step ${progress.planPosition.stepIndex}/${progress.planPosition.stepCount} (${progress.planPosition.completionPct.toFixed(0)}%)]`
      : `[step ${progress.stepsUsed}/${progress.maxSteps}]`
    const line = `${prefix}${label ? ` ${label}…` : ''}`
    process.stdout.write(`\r${line.padEnd(lastProgressLineLength)}`)
    lastProgressLineLength = line.length
  }
  function clearProgress(): void {
    if (lastProgressLineLength === 0) return
    process.stdout.write(`\r${' '.repeat(lastProgressLineLength)}\r`)
    lastProgressLineLength = 0
  }

  // A discrete event, not a progress bar — each call gets its own scrolled-past line
  // (unlike writeProgress's single overwritten \r line), the way Claude Code's own CLI
  // shows a running log of what it's doing. Clears the progress line first so a tool step
  // never gets mangled mid-overwrite.
  function writeToolStep(step: AssistantToolStep): void {
    clearProgress()
    // A denied call reports twice — see AssistantToolStep.deniedReason's doc comment — so the
    // proposal line ("Reading X") a viewer already saw a moment earlier stays on screen and this
    // second line closes the loop instead of replacing it.
    if (step.deniedReason) {
      console.log(`  ${ICONS.deniedStep} Denied: ${step.summary} — ${step.deniedReason}`)
    } else {
      console.log(`  ${toolStepIcon(step.tool)} ${step.summary}`)
    }
    lastTurnToolSteps.push(step)
  }

  /** One question's in-progress answer — the CLI's text-mode counterpart of AskQuestionCard.tsx's QuestionDraft (chat-ui's Q5 rendering). No `showEdit` flag: a note is only ever entered via the explicit `e<n>` command below, so its presence in `editText` already says whether one exists. */
  interface ClarificationDraft {
    selectedLabels: string[]
    editText: string
    freeText: string
  }
  function emptyClarificationDraft(): ClarificationDraft {
    return { selectedLabels: [], editText: '', freeText: '' }
  }

  /** Recommended option(s) first, stable otherwise — mirrors AskQuestionCard.tsx's orderedOptions exactly, so the same question renders its options in the same order on both surfaces. */
  function orderedAskOptions(question: AskQuestion): AskQuestionOption[] {
    const options = question.options ?? []
    return options
      .map((option, index) => ({ option, index }))
      .sort((a, b) => Number(b.option.recommended ?? false) - Number(a.option.recommended ?? false) || a.index - b.index)
      .map(({ option }) => option)
  }

  /** Collapses one question's draft into the wire AskAnswer shape, or null while still unanswered (INV-28) — mirrors AskQuestionCard.tsx's draftToAnswer. */
  function clarificationDraftToAnswer(questionId: string, draft: ClarificationDraft): AskAnswer | null {
    if (draft.selectedLabels.length > 0) {
      return draft.editText.trim()
        ? { questionId, kind: 'selected_with_edit', selectedLabels: draft.selectedLabels, editText: draft.editText.trim() }
        : { questionId, kind: 'selected', selectedLabels: draft.selectedLabels }
    }
    if (draft.freeText.trim()) {
      return { questionId, kind: 'free_text', freeText: draft.freeText.trim() }
    }
    return null
  }

  function printClarificationQuestion(question: AskQuestion, draft: ClarificationDraft, index: number, total: number): void {
    const options = orderedAskOptions(question)
    const allowFreeText = question.allowFreeText !== false
    console.log('')
    if (question.header) console.log(`[${question.header}]`)
    if (total > 1) console.log(`Question ${index + 1} of ${total}`)
    console.log(question.question)
    options.forEach((option, i) => {
      const n = i + 1
      const picked = draft.selectedLabels.includes(option.label) ? '✓' : ' '
      const recommended = option.recommended ? ' (recommended)' : ''
      console.log(`  [${picked}] ${n}) ${option.label}${recommended}`)
      if (option.description) console.log(`        ${option.description}`)
      if (option.preview) console.log(`        preview: ${option.preview}`)
    })
    if (draft.editText) console.log(`  note: ${draft.editText}`)
    if (draft.freeText) console.log(`  other: ${draft.freeText}`)
    const commands = [
      options.length > 0 ? (question.allowMultiple ? '<n>/t<n> toggle option' : '<n> select option') : undefined,
      options.length > 0 ? 'e<n> add a note to a selected option' : undefined,
      allowFreeText ? 'o other (free text)' : undefined,
      total > 1 ? 'b back, n next' : undefined,
      's submit',
    ].filter((c): c is string => c !== undefined)
    console.log(`  (${commands.join(' | ')})`)
  }

  /**
   * Text-mode equivalent of AskQuestionCard.tsx (Q6 of the internal plan):
   * runs a self-contained prompt loop over `result.questions`, then resumes the paused turn by
   * calling back into handleTurn with `pendingClarificationId`/the assembled AskResponse — same
   * "resolved by ID, never re-derived" shape as the write/shell/email pause above. Only reached
   * once the harness has already staged the questions (AskClarificationService.stageAndRespond);
   * this function only collects and validates the answer, it never talks to the harness directly.
   */
  async function handleClarification(result: AssistantTurnResult): Promise<void> {
    const questions = result.questions ?? []
    const pendingClarificationId = result.pendingClarificationId
    if (questions.length === 0 || !pendingClarificationId) {
      // Mirrors shouldRenderAskQuestionCard's guard in chat-ui — shouldn't happen in practice
      // (AskClarificationService always sets both together), but fails safe to the plain-text
      // escalation copy rather than entering a loop with nothing to ask.
      lastTrace = undefined
      lastNoTraceReason = `No harness trace — the last turn needed clarification (${result.reason ?? 'no further detail'}) but had no answerable questions.`
      console.log(`\n[needs clarification] ${result.reason ?? 'This request needs clarification.'}\n`)
      return
    }

    // Same "never touches stdin, always resolves the same way" shape as askYesNo's own decline
    // branch — a piped/scripted run has no one to answer these questions, so it falls through to
    // the plain-text escalation copy instead of blocking on a readline read of closed stdin.
    if (nonInteractiveApprovalMode === 'decline') {
      console.log(`\n[non-interactive mode: auto-declining — ASSISTANT_NON_INTERACTIVE_APPROVAL=decline]`)
      console.log(`\n[needs clarification] ${result.reason ?? 'This request needs clarification.'}`)
      for (const q of questions) console.log(`  - ${q.question}`)
      console.log('')
      lastTrace = undefined
      lastNoTraceReason = 'No harness trace — the last turn needed clarification and was auto-declined (non-interactive mode) before the harness resumed.'
      return
    }

    console.log(`\n[needs clarification] ${questions.length} question${questions.length === 1 ? '' : 's'} to answer.`)
    const drafts = new Map<string, ClarificationDraft>(questions.map((q) => [q.id, emptyClarificationDraft()]))
    let index = 0

    while (true) {
      const question = questions[index]
      const draft = drafts.get(question.id)!
      printClarificationQuestion(question, draft, index, questions.length)
      const token = (await askLine('clarify> ')).trim()
      const lower = token.toLowerCase()

      if (lower === 's' || lower === 'submit') {
        const answers = questions.map((q) => clarificationDraftToAnswer(q.id, drafts.get(q.id)!))
        const missing = questions.filter((q, i) => answers[i] === null)
        if (missing.length > 0) {
          console.log(`\nStill need an answer for: ${missing.map((q) => q.question).join('; ')}\n`)
          continue
        }
        const response: AskResponse = { answers: answers as AskAnswer[] }
        await handleTurn('', false, undefined, pendingClarificationId, response)
        return
      }
      if (lower === 'b' && questions.length > 1) {
        index = Math.max(0, index - 1)
        continue
      }
      if (lower === 'n' && questions.length > 1) {
        index = Math.min(questions.length - 1, index + 1)
        continue
      }
      if (lower === 'o') {
        if (question.allowFreeText === false) {
          console.log('\nThis question does not accept a free-text answer.\n')
          continue
        }
        const text = await askLine('Other — type your own answer: ')
        if (!text.trim()) {
          console.log('\nEmpty answer ignored.\n')
          continue
        }
        drafts.set(question.id, { selectedLabels: [], editText: '', freeText: text.trim() })
        continue
      }
      const editMatch = /^e(\d+)$/i.exec(token)
      if (editMatch) {
        const options = orderedAskOptions(question)
        const option = options[Number(editMatch[1]) - 1]
        if (!option) {
          console.log(`\nNo option ${editMatch[1]}.\n`)
          continue
        }
        if (!draft.selectedLabels.includes(option.label)) {
          console.log(`\nSelect option ${editMatch[1]} first, then add a note with e${editMatch[1]}.\n`)
          continue
        }
        const note = await askLine('Note: ')
        drafts.set(question.id, { ...draft, editText: note.trim() })
        continue
      }
      const toggleMatch = /^t(\d+)$/i.exec(token) ?? /^(\d+)$/.exec(token)
      if (toggleMatch) {
        const options = orderedAskOptions(question)
        const option = options[Number(toggleMatch[1]) - 1]
        if (!option) {
          console.log(`\nNo option ${toggleMatch[1]}.\n`)
          continue
        }
        if (question.allowMultiple) {
          const already = draft.selectedLabels.includes(option.label)
          drafts.set(question.id, {
            ...draft,
            selectedLabels: already ? draft.selectedLabels.filter((l) => l !== option.label) : [...draft.selectedLabels, option.label],
            freeText: '',
          })
        } else {
          drafts.set(question.id, { ...draft, selectedLabels: [option.label], freeText: '' })
        }
        continue
      }

      console.log(`\nUnrecognized input "${token}".\n`)
    }
  }

  async function handleTurn(
    message: string,
    approved = false,
    pendingActionId?: string,
    pendingClarificationId?: string,
    clarificationAnswer?: AskResponse,
    planApprovalId?: string,
    planDecision?: PlanDecision,
    planEdits?: PlanApprovalEdits,
  ): Promise<void> {
    lastTurnToolSteps = []
    // Set only once the first token of an actual streamed reply arrives — the
    // message-level approval gate and the file-tools loop both produce a full
    // reply with no streaming, so this stays false for those turns and the
    // final branch below falls back to printing the whole reply at once.
    let streamedAnyTokens = false
    function writeToken(token: string): void {
      if (!streamedAnyTokens) {
        process.stdout.write('\nAielia> ')
        streamedAnyTokens = true
      }
      process.stdout.write(token)
    }

    try {
      const result = await assistant.turn(message, {
        sessionId: 'cli',
        approved,
        pendingActionId,
        pendingClarificationId,
        clarificationAnswer,
        planApprovalId,
        planDecision,
        planEdits,
        // Gated on streamedAnyTokens: onProgress keeps firing for layers (Memory,
        // Verification) that run after the LLM call, i.e. after writeToken has already put
        // the reply on the current line with no trailing newline. writeProgress's \r-based
        // overwrite doesn't know that — on a real TTY it wrote the "[step N/5] ..." text
        // over the tail of the just-streamed reply, and the following clearProgress() then
        // blanked that same line, so the end of the assistant's answer visibly vanished
        // right after it finished streaming. Once streaming has started this turn, further
        // progress has nothing safe to overwrite, so it's dropped instead.
        onProgress: (progress) => {
          if (progress.planTasks) options.onPlanProgress?.(progress.planTasks)
          if (!streamedAnyTokens) writeProgress(progress)
        },
        onToken: writeToken,
        onToolStep: writeToolStep,
        // Phase 4 — real intra-turn absorption via checkCallerUpdates, replacing Phase 3's
        // drain-as-follow-up-turns fallback in dispatchOne's `finally` below (kept there, but
        // only as a backstop: turn() re-enqueues anything it didn't get around to classifying
        // this turn — e.g. a trivial turn that never calls harnessBridge.run() at all — back onto
        // this same channel, see TurnOptions.steeringChannel's doc comment). Passed unconditionally:
        // with goalGraphMode off, routeMessage (below) never enqueues into steeringChannel, so it's
        // always empty and this resolves to exactly today's behavior (INV-43).
        steeringChannel,
      })
      // Same streamedAnyTokens gate as onProgress above: lastProgressLineLength describes a
      // pre-streaming progress line that a leading "\n" in writeToken already scrolled past,
      // not the current line (the tail of the streamed reply) — clearing unconditionally here
      // would \r back onto the reply's last line and blank the start of it with stale-length
      // spaces.
      if (!streamedAnyTokens) clearProgress()

      // A write_file/run_shell_command tool call, gated at the point of the call itself
      // rather than by the message text — see the file-tools and web+shell-tools plans'
      // Diagnosis tabs. Unlike the message-level gate below, both a yes and a no need to
      // re-call turn() (to apply or discard the staged action), not just a yes.
      if (result.status === 'needs_approval' && result.pendingActionId) {
        // 'batch' (a projected-search-count confirmation, not a staged write/shell action) has
        // its own label and prompt — falling through to the 'write' case here would print
        // "[needs approval — write]" and "Apply this write?" over a message that's actually
        // about how many more searches a batch research turn is projected to need.
        const kindLabel =
          result.pendingActionKind === 'shell'
            ? 'shell command'
            : result.pendingActionKind === 'email'
              ? 'send email'
              : result.pendingActionKind === 'batch'
                ? 'batch research'
                : 'write'
        const promptText =
          result.pendingActionKind === 'shell'
            ? 'Run this command?'
            : result.pendingActionKind === 'email'
              ? 'Send this email?'
              : result.pendingActionKind === 'batch'
                ? 'Continue?'
                : 'Apply this write?'
        console.log(`\n[needs approval — ${kindLabel}] ${result.reason}`)
        let confirmed: boolean
        if (result.pendingActionKind && rememberedActionKinds.has(result.pendingActionKind)) {
          console.log(`["don't ask again" active this session for ${kindLabel} — auto-approved]`)
          confirmed = true
        } else {
          const decision = await askSelect(promptText, APPROVAL_OPTIONS)
          confirmed = decision !== 'n'
          if (decision === 'a' && result.pendingActionKind) rememberedActionKinds.add(result.pendingActionKind)
        }
        lastTrace = undefined
        lastNoTraceReason = `No harness trace — the last turn was a staged ${kindLabel} that was ${confirmed ? 'approved' : 'declined'} before the harness ran.`
        await handleTurn(message, confirmed, result.pendingActionId)
        return
      }

      if (result.status === 'needs_approval') {
        console.log(`\n[needs approval — ${result.riskLevel}] ${result.reason}`)
        console.log(`  "${message}"`)
        let confirmed: boolean
        if (result.riskLevel && rememberedRiskLevels.has(result.riskLevel)) {
          console.log(`["don't ask again" active this session for risk level ${result.riskLevel} — auto-approved]`)
          confirmed = true
        } else {
          const decision = await askSelect('Proceed?', APPROVAL_OPTIONS)
          confirmed = decision !== 'n'
          if (decision === 'a' && result.riskLevel) rememberedRiskLevels.add(result.riskLevel)
        }
        if (confirmed) {
          await handleTurn(message, true)
        } else {
          // Without clearing lastTrace here, /why and /layers only fall back to
          // lastNoTraceReason when lastTrace is unset — so once any earlier turn in the
          // session had produced a real trace, a later decline left that stale trace in
          // place and printWhy/printLayers displayed the wrong (already-finished) turn's
          // explanation instead of this decline's reason.
          lastTrace = undefined
          lastNoTraceReason = 'No harness trace — the last turn was blocked on an approval gate and declined before the harness ran.'
          // Recorded now (not inside turn() itself) because the outcome is only known here —
          // see recordDeclinedRequest's doc comment for why this is safe unlike an eager append
          // inside runTurn. Without it, a later "did that actually happen?" question found no
          // trace of the request at all and confidently denied it was ever made.
          await assistant.recordDeclinedRequest('cli', message, result.reason ?? 'This request needed approval.')
          console.log('Cancelled.\n')
        }
        return
      }

      if (result.status === 'needs_clarification') {
        await handleClarification(result)
        return
      }

      // P2's whole-plan approval gate — the CLI surface for it, mirroring chat-ui's
      // PlanApprovalCard + its approve/approve-with-edits/approve-trusted/decline handlers, all
      // resolving through the same PlanApprovalService. Before this branch existed the CLI fell
      // through to the ordinary render below, so a staged plan (whose result carries reply: null)
      // printed as a bare "- null" and could not be approved, edited, or declined at all.
      if (result.status === 'needs_plan_approval') {
        if (!result.planApprovalId) {
          console.log(`\n[needs plan approval] ${result.reason ?? 'A plan is awaiting approval, but its approval id is missing.'}\n`)
          return
        }
        const id = result.planApprovalId
        const snapshot = result.planApproval
        if (result.reason) console.log(`\n${result.reason}`)
        if (snapshot) printPlanApproval(snapshot)
        // Stashed (not just resolved inline) so the /plan approve|edit|decline commands can finish
        // the job if the user picks "decide later" below.
        pendingPlanApproval = { id, message, snapshot }
        lastTrace = undefined
        lastNoTraceReason = 'No harness trace — the last turn staged a plan for approval (pending /plan approve|decline|edit).'
        if (!snapshot) {
          console.log('Decide with /plan approve or /plan decline.\n')
          return
        }
        const choice = await askSelect('Approve this plan?', PLAN_APPROVAL_OPTIONS)
        if (choice === 'd') {
          console.log('Left pending — /plan to review, /plan approve|edit|decline to decide.\n')
          return
        }
        pendingPlanApproval = undefined
        let decision: PlanDecision
        let edits: PlanApprovalEdits | undefined
        if (choice === 't') {
          decision = 'approve_trusted'
        } else if (choice === 'e') {
          edits = await promptPlanEdits(snapshot)
          decision = 'approve_with_edits'
        } else if (choice === 'y') {
          decision = 'approve'
        } else {
          decision = 'decline'
        }
        lastNoTraceReason = `No harness trace — the last turn staged a plan that was ${decision === 'decline' ? 'declined' : 'approved'} before the harness ran.`
        // Same originating message, so an approve falls through to the ordinary pipeline with the
        // now-active plan (see PlanApprovalService.resolvePendingPlanApproval's doc comment) exactly
        // the way a freshly template-matched plan already does.
        await handleTurn(message, false, undefined, undefined, undefined, id, decision, edits)
        return
      }

      if (result.status === 'escalated') {
        lastTrace = undefined
        lastNoTraceReason = `No harness trace — the last turn escalated (${result.reason}) before completing.`
        console.log(`\n[escalated] ${result.reason}\n`)
        return
      }

      // A trivial turn's trace is present-but-empty (see assistant.ts's triviality branch) so
      // chat-ui can still render its "Why?"/"Run detail" panels with an explanation and an
      // all-unfired grid — the CLI has no such grid, so it keeps printing its existing plain
      // "took the fast path" copy instead of an empty/misleading confidence readout.
      //
      // A resolved write_file/run_shell_command/revert pendingAction (assistant.ts's
      // resolvePendingAction, reached whenever this call passed a `pendingActionId`) returns
      // neither harnessSkipped nor trace at all — it's not the trivial fast path, it just never
      // runs the per-turn HarnessRuntime. Both call sites that recurse into this same handleTurn()
      // to resolve one (the pendingActionKind branch below and handleUndoAction) already set
      // lastNoTraceReason to a specific, accurate "staged ${kind} that was approved/declined
      // before the harness ran" message right before recursing — unconditionally falling through
      // to the generic fallback here clobbered that back to undefined, which is exactly what made
      // /why and /layers report the wrong (fully generic) reason after any staged tool-call
      // resolution. Guard on the `pendingActionId` parameter (not the result shape, which a test
      // mock may reasonably leave sparse) so this block is skipped entirely for a pendingAction
      // resolution, leaving the caller's already-correct state alone.
      if (!pendingActionId) {
        lastTrace = result.harnessSkipped ? undefined : result.trace
        lastNoTraceReason = result.harnessSkipped
          ? 'No harness trace — the last turn was a simple, self-contained question answered directly without activating the harness (fast path).'
          : undefined
      }
      lastSources = result.sources
      // A trivial fast-path turn never touches plan state at all (assistant.ts's triviality
      // branch returns before ever loading/updating activePlan) — result.planStatus is always
      // undefined there regardless of whether a plan is genuinely active, so clobbering
      // lastPlanStatus on every turn made /plan wrongly report "No active plan" right after any
      // ordinary Q&A aside during an in-progress plan (planStatus's own doc comment: it "can be
      // non-null across many consecutive turns" — a harness-skipped turn just doesn't know either
      // way). Same reasoning applies to a resolved pendingAction (resolvePendingAction never
      // touches plan state either, same as the trivial path) — the `pendingActionId` guard above
      // covers both cases.
      //
      // The plan-mode drafting path is the one deliberate exception: PlanDraftingService's
      // results are harnessSkipped (INV-30 — drafting runs no tool loop) yet DO carry a real
      // planStatus for the draft they just built or revised, and so does TurnInterpreter's
      // plan-task-cancel bypass. The old `!result.harnessSkipped` gate silently dropped those —
      // the drafting reply printed its inline "(plan: 0% — /plan)" hint (line below, which reads
      // result.planStatus directly) while /plan then answered "No active plan for this session".
      // Record whenever the turn ran the pipeline OR actually reported a planStatus; a
      // harness-skipped turn with no planStatus (trivial fast path, plan sketch) still leaves the
      // last known plan untouched, and a non-skipped turn reporting none still clears it.
      if (!pendingActionId && (!result.harnessSkipped || result.planStatus)) lastPlanStatus = result.planStatus
      lastTurnUsage = result.usage ? withCostEstimate(result.usage) : undefined
      const riskSuffix = result.riskLevel && result.riskLevel !== 'LOW' ? ` [risk: ${result.riskLevel}]` : ''
      const sourcesHint = result.sources && result.sources.length > 0 ? ` (${result.sources.length} source${result.sources.length > 1 ? 's' : ''} — /sources)` : ''
      const planHint = result.planStatus ? ` (plan: ${result.planStatus.completionPct.toFixed(0)}% — /plan)` : ''
      // Printed as its own line, not folded into riskSuffix/sourcesHint/planHint's inline
      // "${...}" style — this is a full sentence, not a short bracketed tag. Must be handled the
      // same way in both branches below (like the other hints), since result.contradictionNotice
      // is only known once HarnessRuntime.run() finishes, well after writeToken already streamed
      // `reply` itself to the screen — see assistant.ts's findContradictionNotice doc comment.
      const contradictionNotice = result.contradictionNotice ? `\n\n${result.contradictionNotice}` : ''
      // Same treatment for the change reviewer's advisory notice (see AssistantTurnResult.reviewNotice).
      const reviewNotice = result.reviewNotice ? `\n\n${result.reviewNotice}` : ''
      // R7: the turn-end next-step options, under the reply. Remembered so a bare 1/2/3 typed as
      // the very next input runs that option (see dispatchOne); any other input clears them.
      lastNextSteps = result.nextSteps && result.nextSteps.length > 0 ? result.nextSteps : undefined
      const nextStepsBlock = lastNextSteps ? `\n\n${formatNextSteps(lastNextSteps)}` : ''
      if (streamedAnyTokens) {
        // The reply text is already on screen, printed token-by-token as it streamed in — but
        // onToken only ever saw draftReply, not a Phase 4.1 pausedNote appended afterward (see
        // AssistantTurnResult.pausedNote's doc comment), so that part still needs printing here.
        const pausedNoteText = result.pausedNote ? `\n\n${result.pausedNote}` : ''
        process.stdout.write(`${pausedNoteText}${riskSuffix}${sourcesHint}${planHint}${contradictionNotice}${reviewNotice}${nextStepsBlock}\n\n`)
      } else {
        console.log(`\nAielia>${riskSuffix} ${result.reply}${sourcesHint}${planHint}${contradictionNotice}${reviewNotice}${nextStepsBlock}\n`)
      }
    } catch (err) {
      // Mirrors chat-ui's error bubble: a failed turn (e.g. proxy down) shouldn't
      // crash the REPL via an unhandled rejection — just report it and keep going.
      clearProgress()
      const { message: errorMessage, retryable } = classifyError(err, config.llmBackend)
      console.log(`\n[error] ${errorMessage}${retryable ? ' Type the message again to retry.' : ''}\n`)
    }
  }

  // Fails closed: a non-TTY (piped/scripted) stdin is read and closed eagerly by readline,
  // often before a slow turn (one that ran tool calls before hitting a risk gate) even reaches
  // this prompt — rl.question() then throws ERR_USE_AFTER_CLOSE instead of ever reading an
  // answer. Left uncaught, that exception unwound past this function entirely: the caller's
  // `confirmed` was never assigned, "Cancelled." was never logged, and the line meant as the
  // answer was left to be dispatched as its own ordinary chat turn instead (readline had already
  // queued it as a 'line' event before this prompt ever ran) — a HIGH-risk/destructive request
  // was silently neither approved nor declined rather than being safely stopped. Any failure to
  // read a real answer must resolve to "no" (never "yes"), so a broken/absent confirmation
  // channel can't be mistaken for approval.
  function askYesNo(question: string): Promise<boolean> {
    // Test-only seam: bypasses stdin/readline entirely, same "never touches stdin" shape as the
    // nonInteractiveApprovalMode === 'decline' branch below, just with a caller-scripted answer
    // instead of a hardcoded decline.
    if (options.askYesNo) return options.askYesNo(question)
    // A designed decision, not a fallback: never touches stdin, so there's no readline race to
    // land in — unlike the catch below, this path is reached deterministically on every
    // approval gate, not only when reading the answer happens to fail.
    if (nonInteractiveApprovalMode === 'decline') {
      console.log(`\n[non-interactive mode: auto-declining — ASSISTANT_NON_INTERACTIVE_APPROVAL=decline]`)
      return Promise.resolve(false)
    }
    return new Promise((resolve) => {
      try {
        rl.question(question, (answer) => resolve(answer.trim().toLowerCase().startsWith('y')))
      } catch {
        console.log(`\n[could not read a response — treating as declined]`)
        resolve(false)
      }
    })
  }

  /**
   * Free-text counterpart of askYesNo, for the clarification sub-loop's option numbers, edit
   * notes, and "Other" free text. handleClarification's own nonInteractiveApprovalMode ===
   * 'decline' branch returns before ever calling this, so — unlike askYesNo — there's no decline
   * branch to mirror here; the same fail-closed "never throw past the caller" shape still applies
   * for the read-failure case, just resolving to an empty string (an unrecognized/ignored answer,
   * see printClarificationQuestion's callers) instead of askYesNo's "treat as declined" boolean.
   */
  function askLine(question: string): Promise<string> {
    // Test-only seam — same shape as askYesNo's own.
    if (options.askLine) return options.askLine(question)
    return new Promise((resolve) => {
      try {
        rl.question(question, (answer) => resolve(answer.trim()))
      } catch {
        console.log(`\n[could not read a response — treating as blank]`)
        resolve('')
      }
    })
  }

  /**
   * Structured multi-option counterpart of askYesNo/askLine (Phase 7's approval selector). The
   * Ink shell overrides this with `PromptBridge.askSelect`, which routes to `SelectPrompt`'s
   * real arrow-key/shortcut-key UI (`ink-select-prompt.tsx`); this plain-`readline` fallback is
   * what a non-TUI REPL (or a piped/non-interactive session) actually reads from. Resolves with
   * the chosen option's `key` — never the option's index or label. `selectOptions` is ordered by
   * every call site with its safe/fail-closed choice last (mirroring askYesNo's own "no real
   * answer → treat as declined" direction), and every failure-to-read path here resolves to that
   * last option's key, never the first — same fail-closed reasoning as askYesNo's own doc comment
   * above.
   */
  function askSelect(question: string, selectOptions: SelectOption[]): Promise<string> {
    // Test-only seam — same shape as askYesNo's/askLine's own.
    if (options.askSelect) return options.askSelect(question, selectOptions)
    const fallbackKey = selectOptions[selectOptions.length - 1]!.key
    if (nonInteractiveApprovalMode === 'decline') {
      console.log(`\n[non-interactive mode: auto-declining — ASSISTANT_NON_INTERACTIVE_APPROVAL=decline]`)
      return Promise.resolve(fallbackKey)
    }
    const optionLines = selectOptions.map((option, i) => `  ${i + 1}) [${option.key}] ${option.label}`).join('\n')
    return new Promise((resolve) => {
      try {
        rl.question(`${question}\n${optionLines}\n> `, (answer) => {
          const trimmed = answer.trim().toLowerCase()
          const byKey = selectOptions.find((option) => option.key.toLowerCase() === trimmed)
          const byIndex = /^\d+$/.test(trimmed) ? selectOptions[Number(trimmed) - 1] : undefined
          resolve((byKey ?? byIndex)?.key ?? fallbackKey)
        })
      } catch {
        console.log(`\n[could not read a response — treating as declined]`)
        resolve(fallbackKey)
      }
    })
  }

  // Refreshes `config`/`overriddenKeys` from disk and rebuilds `assistant` so a persisted
  // change (set or reset) takes effect on the very next turn — no restart needed. Cheap
  // enough to call unconditionally rather than special-casing which keys "matter": it's
  // just re-running the same wiring buildAssistant/main already do once at startup.
  async function reloadAssistant(): Promise<void> {
    const nextPersisted = await configStore.load()
    ;({ config, overriddenKeys } = resolveConfig(nextPersisted, envOverrides))
    layerPins = applyLayerSettings(sanitizeLayerChoices(config.layers), process.env).pinned
    assistant = options.assistant ?? (await buildAssistant(config, { dataDir, backend, remindersFile }))
  }

  async function handleConfigCommand(args: string[]): Promise<void> {
    if (args.length === 0) {
      console.log(`\n${formatConfigListing(config, overriddenKeys)}\n`)
      return
    }

    if (args[0] === 'set') {
      const key = args[1]
      const raw = args.slice(2).join(' ')
      if (!key || !isConfigKey(key)) {
        console.log(`\n✗ Unknown config key "${key ?? ''}". Known keys: ${CONFIG_KEYS.join(', ')}\n`)
        return
      }
      if (!raw) {
        console.log(`\nUsage: /config set ${key} <value>\n`)
        return
      }
      if (overriddenKeys.has(key)) {
        console.log(`\n✗ "${key}" is pinned by ${ENV_VAR_FOR_CONFIG_KEY[key]} — unset that env var to change it here.\n`)
        return
      }

      let value: unknown
      try {
        value = parseConfigValue(key, raw)
      } catch (err) {
        if (!(err instanceof ConfigValueParseError)) throw err
        console.log(`\n✗ ${err.message}\n`)
        return
      }

      const patch = { [key]: value } as Partial<AssistantConfig>
      try {
        validateConfig(patch, config)
      } catch (err) {
        if (!(err instanceof ConfigValidationError)) throw err
        console.log(`\n✗ ${err.message}\n`)
        return
      }

      await configStore.save(patch)
      await reloadAssistant()
      console.log(`\n✓ ${key} updated (took effect immediately, no restart needed)\n`)
      return
    }

    if (args[0] === 'reset') {
      const key = args[1]
      if (key && !isConfigKey(key)) {
        console.log(`\n✗ Unknown config key "${key}". Known keys: ${CONFIG_KEYS.join(', ')}\n`)
        return
      }
      // Takes effect immediately, same as /config set — and can silently break the active
      // session (e.g. reverting llmBackend mid-conversation, see conv81's finding), so this asks
      // first, same as any other consequential action (shell commands, writes, HIGH-risk
      // requests) — /config set is left as-is (a single, explicit, intentional value the user
      // just typed, not a broad "wipe back to defaults" that's easy to trigger without meaning to
      // reset something specific).
      const target = key ? `"${key}"` : 'ALL settings'
      const confirmed = await askYesNo(`\nReset ${target} to default? This takes effect immediately. (y/N) `)
      if (!confirmed) {
        console.log('\nCancelled — nothing was reset.\n')
        return
      }
      const clearPatch = key
        ? ({ [key]: undefined } as Partial<AssistantConfig>)
        : (Object.fromEntries(CONFIG_KEYS.map((k) => [k, undefined])) as Partial<AssistantConfig>)
      await configStore.save(clearPatch)
      await reloadAssistant()
      console.log(`\n✓ Reset ${key ?? 'all settings'} to default\n`)
      return
    }

    console.log('\nUsage: /config | /config set <key> <value> | /config reset [key]\n')
  }

  /**
   * `/layers settings|on|off|reset` — list the reasoning layers and switch one on or off (bare `/layers` is printLayers' last-turn view). Persists `config.layers` through the same store as /config and
   * re-applies the flags immediately; floor layers are locked and an operator-set AUDIT_* flag is reported as pinned.
   */
  async function handleLayers(args: string[]): Promise<void> {
    const [sub, id] = args
    if (sub === 'settings' || sub === 'list') {
      console.log(`\n${formatLayerListing(sanitizeLayerChoices(config.layers), layerPins, process.env)}\n`)
      return
    }
    try {
      if (sub === 'on' || sub === 'off') {
        if (!id) { console.log(`\nUsage: /layers ${sub} <id>\n`); return }
        const layers = withLayerChoice(sanitizeLayerChoices(config.layers), id, sub === 'on')
        await configStore.save({ layers })
      } else if (sub === 'reset') {
        const layers = id ? withLayerChoice(sanitizeLayerChoices(config.layers), id, undefined) : {}
        await configStore.save({ layers })
      } else {
        console.log('\nUsage: /layers settings | /layers on <id> | /layers off <id> | /layers reset [id]\n')
        return
      }
    } catch (err) {
      if (!(err instanceof LayerSettingError)) throw err
      console.log(`\n✗ ${err.message}\n`)
      return
    }
    await reloadAssistant()
    const pinned = id !== undefined && layerPins.has(id)
    console.log(pinned ? `\n✗ Saved, but "${id}" is pinned by its AUDIT_* env flag, so the saved choice has no effect until that is unset.\n` : `\n✓ Layers updated (took effect immediately, no restart needed)\n`)
  }

  /** Thin convenience wrapper over /config set model — not a second mechanism. Bare /model shows the current value. */
  async function handleModel(args: string[]): Promise<void> {
    if (args.length === 0) {
      console.log(`\n${config.model ?? "(using each backend's default)"}\n`)
      return
    }
    await handleConfigCommand(['set', 'model', args.join(' ')])
  }

  /**
   * Thin convenience wrapper over /config set|reset activeProject — same relationship handleModel
   * has to /config set model. Bare /project shows the resolved current value (an explicit override
   * if one is set, else the workspace root buildAssistant derived it from — see
   * PersonalAssistant.getActiveProject's doc comment for why this is never itself undefined once
   * the assistant is built). /project clear reverts to that workspace-derived default.
   */
  async function handleProject(args: string[]): Promise<void> {
    if (args.length === 0) {
      console.log(`\n${assistant.getActiveProject() || '(none)'}\n`)
      return
    }
    if (args[0] === 'clear') {
      await handleConfigCommand(['reset', 'activeProject'])
      return
    }
    await handleConfigCommand(['set', 'activeProject', args.join(' ')])
  }

  // Phase 3 of plans/hierarchical_goal_tree_and_steering_plan.html (R1, mid-task steering).
  // `turnInProgress` is true only while dispatchOne is awaiting an actual conversational
  // handleTurn() call, never while a command handler (e.g. /config) is running — so a /config
  // dispatch in flight is completely unaffected and keeps its existing dispatchQueue
  // serialization (the race-avoidance this queue exists for in the first place). `steeringChannel`
  // has no consumer yet beyond the drain in dispatchOne's `finally` below — Phase 4 replaces that
  // drain with real intra-turn absorption via checkCallerUpdates.
  let turnInProgress = false
  // The next-step options the last full turn offered — consumed by the next input (see dispatchOne).
  let lastNextSteps: NextStepSuggestion[] | undefined
  const steeringChannel = new LiveSteeringChannel()

  // A lookup keyed by the message's first whitespace-separated token — replaces what used to
  // be a growing `if (message === '/why') ... if (message === '/sources') ...` chain. Each
  // handler receives the remaining tokens as `args` (empty for commands that take none).
  // Rebuilt on every dispatch rather than hoisted to module scope because several handlers
  // close over `config`/`overriddenKeys`/`assistant`, which reloadAssistant() reassigns.
  const commands: Record<string, (args: string[]) => void | Promise<void>> = {
    '/why': () => printWhy(),
    // Bare /layers is the last-turn fired/skipped view; its subcommands (settings/on/off/reset) edit the on/off choices.
    '/layers': (args) => (args.length === 0 ? printLayers() : handleLayers(args)),
    '/sources': () => printSources(),
    '/plan': (args) => handlePlan(args),
    '/help': () => printHelp(),
    '/clear': () => handleClear(),
    '/new': () => handleClear(),
    '/status': () => printStatus(),
    '/export': (args) => handleExport(args),
    '/undo': () => handleUndo(),
    '/undo-action': (args) => handleUndoAction(args),
    '/memory': (args) => handleMemory(args),
    '/search': (args) => handleSearch(args),
    '/goals': () => handleGoals(),
    '/model': (args) => handleModel(args),
    '/project': (args) => handleProject(args),
    '/cost': () => printCost(),
    '/doctor': () => handleDoctor(),
    '/config': (args) => handleConfigCommand(args),
    '/checkpoint': (args) => handleCheckpoint(args),
  }

  // readline's 'line' event fires for every buffered line as soon as it's parsed — it does
  // not wait for a previous line's async handler to finish, so piped/pasted multi-line input
  // can dispatch several commands concurrently. That's harmless for read-only commands
  // (/why, /sources, a plain turn) but not for /config: two concurrent handleConfigCommand
  // calls read and validate against the same in-memory `config` before either's update lands,
  // which can both corrupt the on-screen result and validate against stale state. Chaining
  // every dispatch onto `dispatchQueue` makes the loop a real REPL — one command fully
  // resolves before the next begins — matching what a human typing into the prompt would
  // experience anyway.
  async function dispatchOne(message: string): Promise<void> {
    if (quitting) return
    // The documented piped workflow ends with a bare `exit` line (`printf 'msg\nexit\n' | node dist/cli.js`);
    // with no handler it used to go to the model as an ordinary turn (and mint a goal thread). Only the
    // bare word counts — "exit strategy for my startup" is still a message.
    if (isQuitCommand(message)) {
      quitting = true
      // M3: refresh the conversation's handoff digest at the session edge (no-op unless AUDIT_EPISODIC_DIGEST is on; fail-open).
      try { await assistant.endSession('cli') } catch { /* a digest failure must never block exit */ }
      console.log('Exiting.')
      rl.close()
      return
    }
    // A bare 1/2/3 right after a turn's next-step options runs that option; anything else drops them.
    const pick = /^[1-3]$/.test(message) && lastNextSteps ? lastNextSteps[Number(message) - 1] : undefined
    lastNextSteps = undefined
    if (pick) {
      console.log(`  → ${pick.description}`)
      message = pick.description
    }
    const [token, ...args] = message.split(/\s+/)
    const handler = commands[token]
    if (handler) {
      await handler(args)
      return
    }
    turnInProgress = true
    try {
      await handleTurn(message)
    } finally {
      turnInProgress = false
      // Phase 4: assistant.turn() above now absorbs queued steering messages in real time via
      // checkCallerUpdates (goal-graph-reconcile.ts), and re-enqueues onto steeringChannel
      // anything it didn't get around to this turn (a trivial turn that skipped harnessBridge.run
      // entirely, or a run that ended before the queue fully drained). This drain is the backstop
      // for exactly that leftover case — dispatched as ordinary follow-up turns, in arrival order,
      // rather than left queued indefinitely. Still satisfies "never silently drop the new ask"
      // (R4) the same way it always has; it's just no longer the *only* absorption path.
      if (isGoalGraphEnabled(config.goalGraphMode)) {
        for (const event of steeringChannel.poll()) {
          void enqueue(event.message)
        }
      }
    }
  }

  let quitting = false
  let dispatchQueue: Promise<void> = Promise.resolve()
  // One command fully resolves before the next begins — see the comment this used to carry
  // inline here (still true): readline's 'line' event doesn't wait for a previous line's async
  // handler, so piped/pasted multi-line input (or a test calling dispatchLine back to back)
  // could otherwise dispatch several commands concurrently, corrupting /config's read-modify-write.
  function enqueue(message: string): Promise<void> {
    const result = dispatchQueue
      .then(() => dispatchOne(message))
      // An unexpected throw here must not poison the queue for lines dispatched after it.
      .catch((err) => {
        console.error('[unexpected error]', err)
      })
    dispatchQueue = result
    return result
  }

  function isKnownCommand(message: string): boolean {
    const [token] = message.split(/\s+/)
    return token in commands || isQuitCommand(message)
  }

  /**
   * Phase 3's routing split: with goalGraphMode off (the default — INV-43), this is exactly
   * `enqueue(message)`, byte-identical to before. With it on, a plain-turn message (not a slash
   * command — those must keep dispatchQueue's strict serialization, see dispatchOne's
   * turnInProgress comment above) arriving while a turn is already running is absorbed into
   * steeringChannel instead of waiting in line, so the composer/prompt never blocks on it (R1).
   */
  function routeMessage(message: string): Promise<void> {
    if (isGoalGraphEnabled(config.goalGraphMode) && turnInProgress && !isKnownCommand(message)) {
      steeringChannel.enqueue(message)
      console.log('\n[queued — the current turn is still running; this will be taken into account once it finishes]\n')
      return Promise.resolve()
    }
    return enqueue(message)
  }

  rl.on('line', (line) => {
    const message = line.trim()
    if (!message) { rl.prompt(); return }
    void routeMessage(message).finally(() => rl.prompt())
  })
  // Safe to resume now — the 'line' listener right above is in place, so anything already
  // buffered on stdin (see the rl.pause() call up top) gets parsed and delivered, not dropped.
  rl.resume()

  return {
    dispatchLine: async (line: string) => {
      const message = line.trim()
      if (!message) return
      await routeMessage(message)
    },
    close: () => rl.close(),
    getPlanGraphNodes: async (live) => (isPlanGraphEnabled(config.planGraphMode) ? loadPlanGraphNodes(live) : undefined),
    getStatusIndicators: async () => {
      const indicators: string[] = []
      // Persistent context, not a notable/active state — always shown, same reasoning as the
      // spend-cap gauge below (once relevant, stays visible rather than only flashing on
      // change). fileTools is wired unconditionally in buildAssistant() (unlike shell/web/email
      // tools), so there's always an effective workspace root to show; mirrors the same
      // `config.workspaceRoot ?? process.cwd()` fallback buildAssistant() itself uses.
      indicators.push(`Workspace: ${config.workspaceRoot ?? process.cwd()}`)
      // A standing risk state, not a one-off event — worth keeping visible for the rest of the
      // session the same way dangerBanner warns once at startup (line ~349), since that startup
      // line scrolls out of view long before the session ends. Only shown when ON, mirroring
      // every other indicator here ("blank when nothing to report").
      if (config.dangerouslySkipPermissions) indicators.push('⚠ Permissions: auto-approved (dangerouslySkipPermissions)')
      if (lastPlanStatus !== undefined) indicators.push('Plan mode: active')
      // Persistent model/token/cost chrome (aielia_cli_formatting_plan.html Phase 1) — reuses
      // the same cumulative spendState counters /cost already reads, so fetching it here once
      // covers both the token/cost indicator and the cap-relative line below (replacing the
      // separate spendCapStatusLine() call, which would otherwise re-fetch the same state).
      indicators.push(`Model: ${config.model ?? backendDisplayModel[config.llmBackend]}`)
      const spendState = await assistant.getSpendState('cli')
      indicators.push(
        `↑${spendState.cumulativeInputTokens.toLocaleString()} ↓${spendState.cumulativeOutputTokens.toLocaleString()} tokens (~$${spendState.cumulativeCostUsd.toFixed(4)})`,
      )
      const spendCapLine = formatSpendCapStatus(spendState, { sessionCostLimitUsd: config.sessionCostLimitUsd, sessionCallLimit: config.sessionCallLimit })
      if (spendCapLine) indicators.push(spendCapLine)
      return indicators
    },
  }
}

/**
 * Phase 4 of the internal plan: `tuiMode` is resolved from the
 * same persisted-config + env-override chain every other config key uses (not just the env var
 * alone), so `/config set tuiMode enabled` works exactly like `/config set oneLoopMode enabled`
 * already does. This is a second, separate `configStore.load()` from the one `runCli()` performs
 * internally — an accepted duplication (one extra small JSON read at startup) rather than
 * threading a pre-resolved config through `runCli()`'s options, since `runCli()` must remain
 * callable on its own (tests, `non-interactive-mode.ts`) with no knowledge of this gate.
 *
 * `shouldLaunchTuiApp` (tui-mode-flag.ts) additionally requires both stdio streams to be a real
 * TTY — this repo's documented piped/scripted workflow (`printf 'msg\nexit\n' | node dist/cli.js`)
 * and every non-interactive shell always take the `runCli()` branch below regardless of the flag.
 * `runTuiApp` is imported dynamically so a disabled (the default) or non-TTY run never loads Ink
 * at all — `main()` behaves byte-for-byte as it does today in both those cases.
 */
export async function main(argv: readonly string[] = process.argv.slice(2)): Promise<void> {
  const parsed = parseCliArgs(argv)
  if (parsed.command === 'version') {
    console.log(CLI_VERSION)
    return
  }
  if (parsed.command === 'help') {
    console.log(cliHelpText(CLI_VERSION))
    return
  }
  if (parsed.command === 'update') {
    process.exitCode = await runUpdateCommand({ dryRun: parsed.dryRun })
    return
  }

  const persisted = await defaultConfigStore.load()
  const { config } = resolveConfig(persisted, defaultEnvOverrides)

  // Startup housekeeping + passive update check. Fire-and-forget: never awaited before the prompt
  // renders, never throws (checkForUpdate resolves null on any failure), and gated off entirely for
  // non-interactive sessions and when opted out (see shouldRunPassiveUpdateCheck).
  const isSea = isRunningAsSea()
  if (isSea) cleanupStaleUpdateFiles()
  if (shouldRunPassiveUpdateCheck({ updateCheck: config.updateCheck, env: process.env, stdinIsTty: Boolean(process.stdin.isTTY) })) {
    void checkForUpdate().then((result) => {
      if (result?.updateAvailable) console.log(updateAvailableNotice(result.latestVersion, CLI_VERSION, isSea))
    })
  }

  if (shouldLaunchTuiApp(config.tuiMode ?? 'disabled', Boolean(process.stdout.isTTY), Boolean(process.stdin.isTTY))) {
    const { runTuiApp } = await import('./tui-app.js')
    await runTuiApp()
    return
  }

  await runCli()
}

/**
 * True when `entryArg` (a `process.argv[1]` value) refers to the same file as
 * `moduleHref` (an `import.meta.url`).
 *
 * The naive check — `moduleHref === pathToFileURL(entryArg).href` — breaks
 * whenever the script is launched through the npm bin: `npx
 * @buildaharness/aielia`, a global install, or any
 * `node_modules/.bin` shim all pass a **symlink** to this file as
 * `process.argv[1]`, while Node reports `import.meta.url` as the resolved real
 * path. So resolve `entryArg` to its real path before comparing. `resolveReal`
 * is injected for tests; it defaults to `fs.realpathSync`.
 */
export function entryArgMatchesModule(
  entryArg: string | undefined,
  moduleHref: string,
  resolveReal: (p: string) => string = realpathSync,
): boolean {
  if (entryArg === undefined) return false
  try {
    return moduleHref === pathToFileURL(resolveReal(entryArg)).href
  } catch {
    return false
  }
}

function isEntryModule(): boolean {
  return entryArgMatchesModule(process.argv[1], import.meta.url)
}

// Guarded so importing this module (e.g. from cli.test.ts, which drives runCli() directly
// instead) never starts a second live REPL against the real process.stdin/stdout and the real
// ~/.buildaharness/personal-assistant data directory. Correctly resolves argv[1] vs.
// import.meta.url for `tsx src/cli.ts` and other unbundled invocations, but this comparison
// is fundamentally unreliable once this module is bundled: Vite/Rollup hoists this file's code
// into a shared chunk (tui-app.ts statically imports runCli/SelectOption from here), so
// import.meta.url inside the built dist/cli.js is that shared chunk's own URL, never
// dist/cli.js's — the guard silently evaluates false and the packaged CLI exits 0 with no
// REPL. bin.ts is the real, never-shared entry for the packaged binary (see its own comment)
// and calls main() unconditionally instead of relying on this check.
if (isEntryModule()) void main()
